WHERE cricos_course_code = '116128J';
UPDATE courses SET
    course_description = '<p><strong>Shape policy, influence decision-making and lead public impact</strong><br/> <br/> UC’s Master of Public Policy is a contemporary, applied and fully online degree designed for professionals working across government, public service and community-focused sectors.</p> <p>In this course you will develop advanced skills to analyse, design and evaluate public policy in a rapidly changing public sector. With a core focus on data analytics, economic modelling, policy analysis and policy evaluation, you will learn how to transform research into actionable policy solutions, manage stakeholder engagement, write professional briefs and respond to real-world challenges facing Australia’s dynamic public sector. Informed by UC’s Indigenous engagement strategy, this course reflects the University’s commitment to addressing complex and critical issues facing Australia’s public sector. </p> <p>Tailor your study pathway through flexible entry and exit points, including graduate certificates or a graduate diploma that articulate into the Master’s. Taught by experts with close ties to the policy community, the program ensures your learning reflects current practice and prepares you for impactful roles in diverse policy environments.</p> <p><strong>Study a Master of Public Policy at UC and you will:</strong></p> <ul> <li> <p>analyse and evaluate public policies using contemporary policy frameworks, data analytics and evidence-based approaches.</p> </li> <li> <p>apply economic modelling and quantitative methods to inform effective public policy decision-making.</p> </li> <li> <p>develop advanced skills in policy design, implementation and evaluation across government and non-government contexts.</p> </li> <li> <p>critically examine complex public sector challenges, including social, economic and governance issues in Australia’s dynamic policy environment.</p> </li> <li> <p>build practical advocacy and leadership skills to influence policy outcomes across the public, private and not-for-profit sectors.</p> </li> </ul> <p><strong>Career opportunities</strong></p> <ul> <li> <p>Policy Analyst</p> </li> <li> <p>Public Policy Advisor</p> </li> <li> <p>Senior Policy Officer</p> </li> <li> <p>Government Relations Manager</p> </li> <li> <p>Program or Project Manager</p> </li> <li> <p>Public Sector Manager</p> </li> <li> <p>Advocacy and Stakeholder Engagement Lead</p> </li> <li> <p>Not-for-Profit Policy Manager</p> </li> <li> <p>Research and Evaluation Specialist</p> </li> </ul> 100% Online <p>UC''''s 100% online Master of Public Policy will help you deliver policies that transform experiences and positively impact communities across the public realm. Click through to download our course brochure to learn more.</p> <p><a href="https://studycanberra.online/online-courses/master-of-public-policy">Enquire Now</a></p>',
    

    entry_requirements = '<p>A completed bachelors degree or completion of the Graduate Diploma in Public Policy or the Graduate Certificate in Public Policy or the Graduate Certificate in Policy Evaluation.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 1 </td> <td>18 January 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 2 </td> <td>15 March 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 3 </td> <td>10 May 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 4 </td> <td>05 July 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 5 </td> <td>30 August 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 6 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>University Of Canberra</b></p> <p> <a href="/credit/35391">Graduate Certificate in Gender Policy (35391)</a> </p> <p> <a href="/credit/35390">Graduate Diploma in Public Policy (35390)</a> </p> <p> <a href="/credit/35389">Graduate Certificate in Public Policy (35389)</a> </p> <p> <a href="/credit/35392">Graduate Certificate in LGBTQIA+ Policy (35392)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/SCM101/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '115326M';
UPDATE courses SET
    course_description = 'Master the art of architecture in the national capital <p>This course has a unique status as the only postgraduate architecture program in Canberra – one of the world’s most internationally recognised and fascinating model design cities. This professionally accredited two-year course focuses on the contemporary issues informing urban architecture and promotes the processes of urbanisation in architectural research.</p> <p>Accredited under a process administered by the Architects Accreditation Council of Australia, the course will arm you with the professional and intellectual knowledge and skills needed to practice architecture nationally and internationally. You will even fine-tune your expertise in related careers, such as urban design and heritage, and can choose to pursue additional studies leading to a PhD in a range of topics, including architectural history, urban planning or digital architecture.</p> Study a Master of Architecture at UC and you will: <ul> <li>understand analytical and theoretical approaches to site, context, program and technologies</li> <li>propose formal, spatial and programmatic resolutions for major urban scale projects</li> <li>demonstrate an understanding of the complex and challenging social, ethical, environmental, political and regulatory contexts within which architectural practice is carried out</li> <li>display an advanced ability to respond to and develop a client brief, scope of work and detailed design proposals up to the start of construction</li> <li>debate the importance of the interconnections of architecture with its cultural, theoretical, technical and historical contexts.</li> </ul> Work Integrated Learning <p>A large proportion of the Master of Architecture course is delivered in collaboration with the local architecture industry – particularly through the degree’s advanced studio units which are taught in collaboration with local practitioners. You will study ‘live’ projects and will have opportunities to network with industry leaders and emerging architects from national and local architecture firms and government agencies who will be invited to assess interim and final studio reviews of your architectural work.</p> Career opportunities <ul> <li>Architect</li> <li>Architectural technologist</li> <li>Architectural heritage specialist</li> <li>Building designer</li> <li>Building scientist</li> <li>Urban designer</li> <li>Policymaker</li> <li>Architectural journalist, researcher or educator</li> <li>BIM modeller</li> <li>3D renderer</li> <li>Project manager</li> </ul> Course specific information <p>To undertake the Master of Architecture, students are required to have an Australian Bachelor of the Built Environment (Architecture) or equivalent and a credit-or-above grade average in Architecture Design Studios in the second and third year of the undergraduate degree. Other students with an Architecture degree or equivalent may be admitted with permission from the course convener, as Recognition of Prior Learning applies to this course. Alternatively, because of the design-based nature of the degree, a portfolio that indicates the design ability of the candidate may be used to determine admission eligibility.</p> <p>Successful completion of both the Bachelor of the Built Environment (Architecture) and the Master of Architecture will enable you to pursue steps leading to professional registration as an architect in Australia.</p> Professional accreditation <p>This course is accredited by Architects Accreditation Council of Australia. Enrolled students are also eligible for an Australian Institute of Architects membership via SONA (Student Organised Network for Architecture).</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Entry into this course requires a Bachelor of Architecture, or equivalent, and a credit (or above) grade average in the architecture design studios in the second and third year of the undergraduate degree. If the credit (or above) grade average is not met a portfolio*, submitted with the application, that indicates the design ability of the candidate may be used to determine admission eligibility. Other students with an Architecture degree or equivalent may be admitted on permission of the course convener. <br/> <br/>*A supporting portfolio is highly recommended to any student with a below credit average grade. The portfolio should demonstrate the final four semesters of studio work or equivalent professional experience.</p> Assumed knowledge <p>Architectural Knowledge in accord with the learning outcomes of the Bachelor of Arts in Architecture, or equivalent.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/913AA/6/2027',
    updated_at = NOW()
WHERE cricos_course_code = '059960J';
UPDATE courses SET
    course_description = 'Do your career justice in the nation’s capital <p>In the Bachelor of Justice Studies, you’ll build a clear understanding of how the justice system works, from its structure and key concepts to the principles that guide it. Studying in Canberra means you’ll learn within a unique legal setting that spans both ACT and federal jurisdictions, giving you a grounded view of how justice policy is developed, managed and applied in real contexts.</p> <p>You can tailor your study with specialist electives that match your interests, including human rights, judicial administration in civil and family law, and criminal justice issues. Along the way, you’ll build practical skills in advocacy, communication, problem solving, negotiation and mediation.</p> <p>When you graduate, you’ll feel ready to step into roles across the civil and criminal justice sectors, helping shape policy, improve access to justice and make a genuine difference. Be the one to make a change.</p> Study a Bachelor of Justice Studies at UC and you will: <ul> <li>learn the fundamentals of the Australian justice system – its core concepts, structure and principles</li> <li>understand the social, legal, economic and political environment affecting the justice sector</li> <li>broad theoretical and technical knowledge about many areas of the justice sector</li> <li>analyse and generate solutions to problems and transmit knowledge and ideas relevant to the sector to others</li> <li>apply your knowledge and skills to demonstrate autonomy, well-developed judgement and responsibility</li> <li>analyse and evaluate information to complete a range of activities relevant to the justice sector</li> <li>work both individually and collaboratively to investigate issues and creatively solve problems that arise within the justice sector</li> <li>develop the relevant cognitive, technical and communication skills to undertake professional roles in research, operations, policy or advocacy.</li> </ul> Work Integrated Learning <p>As part of the course’s Work Integrated Learning (WIL) component, you’ll undertake an internship placement of 75 hours in an area of your choosing. You’ll apply practical skills, including analysis, research, problem solving and writing, in a law or justice workplace. Past student internship examples have included time at community legal centres, courts, the Commonwealth Ombudsman, federal and ACT government departments (including Justice and Community Safety), the Australian Federal Police Association, and community organisations, such as Victim Support ACT and Legal Aid ACT.</p> <p>You’ll also participate in a virtual work experience program where you will study highly practical units, such as dispute management. The program will draw together theoretical, practical and professional skills and knowledge in a capstone project, where you will focus on your real-world area of interest or potential future employment goal.</p> Career opportunities <ul> <li>Probation and parole officer</li> <li>Police officer</li> <li>Policy Officer</li> <li>Border protection officer</li> <li>Community corrections officer</li> <li>Public servant</li> <li>Course-specific information</li> </ul> <p>The Bachelor of Justice Studies is not an accredited course, but is taught in conjunction with the Bachelor of Laws degree, which is accredited by the ACT Law Society.</p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/SCB001/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '095941B';
UPDATE courses SET
    course_description = 'Step into the future of protecting digital infrastructure with Cyber Security at UC.<br/> <p>Expertly designed for graduates and professionals looking to elevate their technical knowledge in cyber security, UC’s Graduate Certificate in Cyber Security offers a comprehensive qualification that will prepare you to protect our digital landscape. Taught with an Australian perspective, you’ll explore the nuances of local, national and international threats and how to navigate them. </p> <p>Enjoy the ultimate flexibility by studying cyber security 100% online. You’ll be able to tackle one subject at a time over a longer semester (minimum 9 weeks). With our unique structure, you can breeze through the course part-time in just 12 months. With an average of just 10 hours of study per week, or 20 hours during winter and summer semester, you can maintain a work-life balance while getting access to all the support through UC''''s online learning. <br/> </p> Study with reduced fees <p>UC’s Graduate Certificate in Cyber Security offers Commonwealth Supported Places (CSP) to domestic students. This means the Australian Government has subsidised a portion of your course, reducing the total balance you are required to pay (known as the student contribution amount).<br/> </p> Study UC’s Graduate Certificate in Cyber Security and you will: <ul> <li>Learn threat detection, mitigation and how to apply attack frameworks and leverage data intelligence to spot and stop cyber threats in their tracks.</li> <li>Boost your organisation''''s digital resilience by mastering cyber security governance frameworks and regulatory requirements. </li> <li>Stay on the cutting edge by exploring the latest in quantum computing, AI, zero trust, the internet-of-things, social engineering and cryptography to stay ahead of cyber threats.</li> <li>Learn to bridge the gap between technical and non-technical stakeholders in cyber security.</li> <li>Master the art of effective communication, ensuring swift responses to cyber incidents that align with your organisation’s established processes.</li> </ul> <p>Industry approved: this course has been developed in collaboration with Cisco and offers students access to globally and local renowned talent via guest lectures and module integration. <br/> </p> Work Integrated Learning <p>At UC, you don’t just learn theory. Our coursework is packed with practical tasks, real-world projects and industry engagement. You’ll have the chance to work directly with industry experts, including Cisco, to gain the insights and skills you need for your career.</p> <p>Test out ideas and build your practical skills via UC''''s sandbox virtual lab environment. You’ll have access to cloud services such as Microsoft Azure, ensuring you engage in practical exercises from the comfort of your home. <br/> </p> Career opportunities <p>A postgraduate cyber security qualification from UC can open doors to an exciting range of career paths in the rapidly growing field of cyber security. With the skills and knowledge gained from this course, you could pursue future cyber security jobs such as:</p> <ul> <li>Cyber Security Analyst</li> <li>Cyber Threat Intelligence Analyst</li> <li>Incident Response Specialist</li> <li>Information Security Consultant</li> <li>IT Governance Specialist</li> <li>IT Security Auditor</li> <li>Risk and Compliance Officer</li> <li>Security Architect</li> <li>Security Consultant</li> <li>Security Operations Centre (SOC) Analyst<br/> </li> </ul> Course-specific information <p>Recognition of prior learning (RPL) may be awarded for work experience exceeding 10 years in a related field of study. Less than 10 years may be accepted on a case-by-case basis.</p> Are you ready to become a formidable digital defender? <p>Download your free course brochure to learn more about UC’s online Graduate Certificate in Cyber Security. </p> <p><a href="https://www.canberra.edu.au/future-students/study-at-uc/about-our-courses/graduate-certificate-in-cyber-security"><strong>Download your free course brochure</strong></a></p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Australian Bachelor qualification in any field or equivalent. <br/> <br/>You can use professional experience and prior learning to enter into a postgraduate qualification at UC through our Professional Pathway Entry program. If you have significant work experience or hold industry-recognised qualifications, this program could be your route to bypass undergraduate study and accelerate your career. Explore Professional Pathway Entry <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry">https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry</a> <br/> <br/>The following Defence members are eligible for direct entry into this course through the Veteran Tertiary Support Program - Postgraduate Course Entry: <br/> <br/>- Commissioned Officer (any rank), <br/>- Chaplain or Maritime Spiritual Wellbeing Officer, <br/>- Senior Non-Commissioned Defence Force Members (E-6 or higher), <br/>- Defence Force Members - Other Ranks (E-2 to E-5) with three or more years'''' experience.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Summer Semester <a href="#"></a></td> <td>23 November 2026</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 <a href="#"></a></td> <td>15 February 2027</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Winter Term <a href="#"></a></td> <td>07 June 2027</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 <a href="#"></a></td> <td>09 August 2027</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/ITC103/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '040739C';
UPDATE courses SET
    course_description = '<p> The University of Canberra''''s Master of Business Administration (MBA) will provide you with the chance to develop high-level competencies relevant to a variety of different types of enterprises. You will study the subtle nuances of business in all its forms, with the view to securing future employment in an executive role, in senior management or as an entrepreneur. Our MBA covers all aspects of business administration, including finance, marketing, economics, strategic processes and people management, and culminates in the completion of a research project of your choice. Due to the course''''s strong focus on Work Integrated Learning (WIL) you will graduate with an impressive portfolio of international experience, as well as the solid business mindset required to negotiate your way through an assortment of legal, industrial and cultural settings, and will be confident interacting in an increasingly complex business environment. </p>',
    course_duration_per_week = 78,

    entry_requirements = '<p>Applicants must have a bachelor qualification in a related field OR Bachelor qualification in an unrelated field AND three years'''' work experience OR Bachelor qualification in an unrelated field AND Graduate Certificate in Business or higher. <br/> <br/>As the course will be taught in English, applicants must have an Academic IELTS of 6.5 or equivalent, with no band score below 6.0. <br/> <br/>For the MBA delivered in Bhutan, course entry admission would normally be through one of the following ways: <br/>(a) Successful completion of the Royal Institute of Management (RIM) Postgraduate Diploma in Financial Management (PGDFM); <br/>(b) Successful completion of the RIM Postgraduate Diploma in Public Administration (PGDPA); or <br/>(c) Successful completion of a Graduate Diploma in Public Administration, Management or other related degree/discipline from an academic institution recognised by UC as being of appropriate academic standing. <br/></p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bhutan</td> <td>MBA Trimester 1 </td> <td>01 February 2027</td> <td></td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/723AL/4/2027',
    updated_at = NOW()
WHERE cricos_course_code = '052826E';
UPDATE courses SET
    course_description = 'Build upon your professional experience with a research degree <p>If you are a business professional looking to extend your expertise and progress your career to the next level, then the Doctorate in Business Administration will help you embrace your past professional and workplace experience to develop a host of relevant research skills. This carefully designed program provides opportunities for advanced study and reflection on practice across a range of professional fields, including accountancy, business management, economics, human resource development, international management, organisational behaviour, and more.</p> <p>You will explore a research subject of your choosing in the form of a dissertation and can tailor the course content to suit your professional interests through your choice of suitable electives.</p> Study a Doctorate in Business Administration at UC and you will: <ul> <li>evaluate and apply specialised knowledge and research skills in planning, demonstrating and justifying a research project in the context of professional practice in a business field</li> <li>demonstrate trans-disciplinary higher order research, analytical and problem-solving skills</li> <li>apply existing professional and other expert skills to great effect in business, business workplaces and the society of the Knowledge Economy</li> <li>illustrate specialised research skills, knowledge and expertise applicable to professional practice or the production and application of knowledge in business</li> <li>demonstrate a systemic and critical understanding of a substantial and complex body of knowledge at the frontier of an area of professional practice in a field of business.</li> </ul> Work Integrated Learning <p>A doctorate is, by its very nature, the embodiment of Work Integrated Learning (WIL), and is much more focused on professional practice than a traditional PhD. Throughout your coursework, and specifically in your dissertation, you will be encouraged to apply your existing professional knowledge and undertake new research to identify and explore a real-world problem in the field of business administration.</p> Career opportunities <ul> <li>Academic</li> <li>Lecturer</li> <li>Sessional academic</li> <li>Senior research officer</li> <li>Senior research fellow</li> <li>Company director</li> <li>General manager</li> <li>Chief executive officer</li> <li>President</li> <li>Vice president</li> <li>Chief financial officer</li> <li>Board member</li> <li>Marketing director</li> <li>Business start-up adviser</li> <li>Entrepreneur</li> <li>Business consultant</li> <li>Public servant</li> <li>Senior policy officer</li> <li>Indigenous program director</li> <li>Human resources director</li> <li>Industrial relations director</li> <li>International diplomat</li> </ul> Course-specific information <p>Before a candidate is admitted to the Doctorate in Business Administration program, the Faculty must be satisfied that it is able to supervise the candidate''''s proposed dissertation, and that the candidate satisfies the following admission requirements:</p> <ol> <li>holds at minimum a bachelor’s degree and a post-bachelor honours year by research, or a master’s or graduate diploma degree of one to two years’ full-time equivalent duration in a relevant field with a Credit or greater average, and evidence of having performed in some subjects relevant to the proposed study at Distinction level or above</li> <li>has five years of professional practice in a relevant area</li> <li>provides evidence of capacity for independent research under the guidance of a supervisory panel at the doctoral level and relevant professional development</li> <li>provides evidence of superior professional performance, both intellectually and technically.</li> </ol> <p>There are non-standard English language requirements for this course. To be eligible you must have an academic IELTS or equivalent of 6.5 with no band score below 6.0. Students who have undertaken all their education in an English-speaking country (as defined on the UC website) are deemed to have met our English language proficiency requirements.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>An applicant may apply for entry into the Professional Doctorate Business Administration (Research) program and the Faculty will determine their eligibility based upon evidence provided which includes: <br/> <br/>a) evidence of knowledge in an area relevant to the proposed doctoral topic; <br/>b) five years of professional practice at a senior level in a relevant area of business, government or law <br/>c) evidence of previous study as demonstrated by a coursework Masters or other education an area relevant to the proposed doctoral topic; and <br/>d) demonstrated ability to undertake complex thinking and problem solving. <br/> <br/>Plus all applicants will: <br/> <br/>e) meet the University''''s minimum English proficiency requirements for entry into higher degree by research courses; <br/>f) satisfy any additional requirements specified for admission of the particular applicant, consistent with University policy.</p> Additional admission requirements <p>Candidates must comply with all requirements of current University of Canberra HDR policies, including those governing submission and examination of theses. Panels of examiners for the award of the Professional Doctorate (Research) (Business Administration) must always include at least one international examiner from a university, research centre or other knowledge node outside Singapore.</p> Assumed knowledge <p>Sufficient knowledge relevant to the study area to enable identification of a need for a new research contribution to an area of professional practice. This includes advanced knowledge of business and organisational contexts.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2026</td> <td>Singapore</td> <td>Research Semester 1 </td> <td>-</td> <td></td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/381JB/1/2026',
    updated_at = NOW()
WHERE cricos_course_code = '052826E';
UPDATE courses SET
    course_description = 'Launch your science career with a bang <p> If you have a love of all things science and want to use that to enliven the minds of young people aged 12 to 18, then this four-year specialist degree is for you. You’ll select two disciplines from a choice of scientific streams, including biology, chemistry, ecology and mathematics and will learn how to align your specialisations to core teaching principles and to the design of programs that celebrate integration, diversity and inclusion. </p> <p> Across several Pedagogical Content Knowledge (PCK) units, taught on-site in a secondary school environment, you’ll explore your theoretical scientific learning in a practical setting, gaining a good understanding of how a secondary school operates. You’ll graduate energised, motivated and enthusiastic, with all the necessary knowledge and skills required to pass on your passion for science to students across Years 7 to 12. </p> Study a Bachelor of Secondary Education (Science) at UC and you will: <ul> <li>Demonstrate specialised knowledge and skills in two science disciplines, across a range of classes and year groups, within a secondary school environment.</li> <li>Learn the theories and principles that are the foundation for educational practice in secondary settings.</li> <li>Demonstrate an understanding of student needs and differences, and develop teaching activities for a range of indigenous, English as an Additional Language or Dialect (EALD) and mainstream settings.</li> <li>Develop and implement effective assessment strategies and carry out evaluation of teaching programs, resources and your own teaching.</li> <li>Apply the required content knowledge for all secondary school curriculum areas to teaching and reporting methods, alternate/enhanced literacy and numeracy strategies, and the effective use of Information and Communication Technologies (ICT) in teaching and learning.</li> </ul> Work Integrated Learning <p> A teaching degree, by its very nature, is the embodiment of Work Integrated Learning (WIL), with its focus on compulsory professional teaching practice. During this course, you’ll undertake a minimum of 80 days of practical placement across a range of different secondary school levels and settings, including science-specific positions, culminating in a 30-day teaching placement in your final year. </p> <p> In addition, the course content is developed by secondary education professionals and kept relevant and up-to-date through consistent monitoring and engagement with the industry. You’ll undertake authentic assessment tasks that are highly relevant to the day-to-day practice of teaching and will take part in regular professional development activities, field trips to educational STeM sites such as Questacon, lectures hosted by guest speakers from a range of education and teaching backgrounds and more. </p> Career opportunities <ul> <li>Secondary School Teacher</li> <li>Science Teacher</li> <li>Chemistry Teacher</li> <li>Biology Teacher</li> <li>Earth and Environmental Science Teacher</li> <li>Physics Teacher</li> <li>Maths Teacher</li> <li>Head of Department</li> <li>Principal</li> <li>Deputy Principal</li> <li>Executive Teacher</li> <li>Head Teacher Welfare</li> <li>Director of Curriculum</li> <li>Year Adviser</li> <li>Special Needs Teacher</li> <li>Gifted and Talented Teacher</li> <li>Relief Teacher</li> <li>Guidance Officer</li> <li>Careers Adviser</li> <li>Learning Support Teacher</li> <li>Student Adviser</li> <li>Education Adviser</li> <li>Schools Policy Adviser</li> <li>Vocational Education and Training Instructor</li> <li>Private Tutor</li> <li>Schools Engagement Coordinator.</li> </ul> Course-specific information <p> This course is registered by the ACT Teacher Quality Institute (TQI) and recognised as a teaching qualification throughout Australia. <br/> <br/> Upon graduating, students must register with the appropriate state teaching body in order to teach. <br/> <br/> Students must obtain a Working with Vulnerable People check before their first placement. </p> Professional accreditation <p>This course is registered by the ACT Teacher Quality Institute (TQI) and recognised as a teaching qualification throughout Australia.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to these courses is based on an entrance rank assessed based on the following criteria: <br/>- Year 12 ATAR <br/>- Other Australian Qualification <br/>- Work experience <br/>- Overseas qualification</p> Additional admission requirements <p>All applicants will be required to complete a written statement in response to questions designed to assess their suitability for the teaching profession. Applicants'''' responses to these questions must be deemed satisfactory for them to be admitted to these courses.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/348JA/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '113223A';
UPDATE courses SET
    course_description = '<p> The Master of Counselling provides advanced training in counselling, as well as a pathway to registration with the Australian Counselling Association – the nation’s professional accreditation body for counsellors and psychotherapists. The course places an emphasis on skills development, interactive teaching, experiential learning and self-awareness, supporting the student to: <br/> </p> <ul> <li>Develop skills in critical thinking, communication, problem solving, and advanced approaches to working with clients.</li> <li>Access experiential, collaborative and holistic approaches to learning, enabling the development of in-depth practical knowledge and skills, self-awareness and reflexivity.</li> <li>Work with a diverse range of clients, respecting the importance of social and cultural contexts.</li> <li>Access the most recent and relevant academic conventions and materials to complete a research project. </li> <li>Students will undertake counselling placements within an appropriate agency, while being guided by qualified clinical supervisors and learning from peers.</li> </ul> <p>This course includes a compulsory placement of 200 hours. Students will be expected to travel up to 1.5 hours to attend a placement, or in the case of regional and remote students, may need to travel further or potentially relocate for the duration of the placement if one cannot be secured in their area. In addition to the placement requirements, students will be required to attend a 5-day intensive workshop in person. The location of this is to be determined, with an on-campus site being certain.</p> <strong>Course duration</strong> <p>Standard 2 years part-time (12 study blocks).* Maximum 5 years from date of enrolment to date of course completion. *The duration is dependent on individual study path and placement requirements.</p> <p>The Master of Counselling is currently not eligible for Austudy assistance through Centrelink. Please visit this website for further information: <a href="https://www.servicesaustralia.gov.au/austudy">Austudy - Services Australia</a></p> Online with expert placement support <p>Whether helping others cope with crisis, put challenges into perspective or find a life worth living, guide the way and practise respectful and inclusive counselling. The Master of Counselling consists of research-led content that is delivered via supported and interactive teaching, while allowing students to undertake experiential learning. Students will work closely with clinical supervisors while undertaking placement units. Click through to download our course brochure to learn more about our online Master of Counselling.</p> <p><a href="https://studyonline.canberra.edu.au/online-courses/master-of-counselling">Enquire now</a></p> Professional accreditation <p>The course is recognised as a professional qualification in counselling and accredited by the Australian Counselling Association (ACA), in line with their Professional Training Standards.</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Admission to this course is competitive. Applications will be assessed on the basis of academic merit, work experience and the number of available places. <br/> <br/>Applicants must: <br/>1. have an undergraduate or postgraduate degree in any discipline. <br/> <br/>No Recognition of Prior Learning (RPL) will be offered for any units included in this course. <br/> <br/>We recommend that students progressing to this course from the Graduate Certificate in Counselling (SCC401) complete the four Graduate Certificate units before progressing to the Graduate Diploma or Master to ensure a smooth enrolment transition.</p> Additional admission requirements <p>Students are required to undergo a National Police check and relevant state-based checks (i.e. Working with Vulnerable People Check, Working With Children Check) as required by each placement agency in order to be accepted for each unit that includes a placement. </p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 1 </td> <td>18 January 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 2 </td> <td>15 March 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 3 </td> <td>10 May 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 4 </td> <td>05 July 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 5 </td> <td>30 August 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 6 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>University Of Canberra</b></p> <p> <a href="/credit/29218">Graduate Diploma in Counselling (29218)</a> </p> <p> <a href="/credit/29238">Graduate Certificate in Counselling (29238)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/SCM401/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '050002F';
UPDATE courses SET
    course_description = '<strong>Where business and technology meet </strong> <p>If you enjoy IT but prefer business analysis and strategy to technical coding or programming, then UC’s Graduate Certificate in Business Informatics is the right course for you. </p> <p>A unique blend of data analytics and business management, you can take your career to new heights, fill a skills gap, or simply learn something new in this course.</p> <p>Designed to introduce you to some of the core concepts of the ‘Information Age’, this course will allow you to explore specific IT areas such as systems modelling, project management, and the use of enterprise systems to support business processes, information flows, reporting and data analytics in complex organisations.</p> <strong>Further your studies </strong> <p>Thinking of upgrading your qualifications? Successful completion of this course serves as a pathway into the Graduate Diploma in Business Informatics and Master of Business Informatics. </p> <strong>Study a Graduate Certificate in Business Informatics at UC and you will:</strong> <ul> <li>learn how to critically analyse complex business processes and build innovative solutions</li> <li>build and derive advanced system models </li> <li>expand your network of professional contacts</li> <li>increase your employment options</li> <li>become skilled in a highly in-demand area.</li> </ul> <strong>Work Integrated Learning (WIL)</strong> <p>Work Integrated Learning (WIL) is a strong focus of the UC Graduate Certificate in Business Informatics course. As such, you will get to regularly connect and engage with the world of professional practice via examination of practical scenarios and industry case studies.</p> <p>As part of your studies, you will also have the opportunity to tailor your studies around your specific areas of interest, or future employment aspirations – or participate in work experience or internships with organisations such as PricewaterhouseCoopers (PwC), Fujitsu Australia, Birdsnest, the University of Canberra, and more.</p> <strong>Career opportunities</strong> <p>The UC Graduate Certificate in Business Informatics is a highly respected industry qualification that is currently in high demand in Australia and around the world. Once you graduate, you will be well-positioned to apply for the following positions:</p> <ul> <li>IT security analyst</li> <li>Business analyst</li> <li>Systems analyst</li> <li>IT project manager</li> <li>ICT consultant</li> <li>Web developer</li> <li>IT systems test engineer</li> <li>Information analyst</li> <li>Data scientist</li> <li>Systems architect</li> <li>Information systems manager</li> <li>IT auditor</li> <li>IT business manager</li> <li>Solutions engineer.</li> </ul> <strong>Course-specific information</strong> <p>To apply, students must have a bachelor’s degree from a recognised Australian university or an accepted overseas institution.</p> <p>A clear pathway of study exists between this degree, the undergraduate Bachelor of Business Informatics, and the postgraduate Graduate Diploma in Business Informatics and Master of Business Informatics courses. Students who have completed this course may apply and receive credit for units within the Graduate Diploma in Business Informatics and Master of Business Informatics.</p>',
    course_duration_per_week = 26,

    entry_requirements = '<p>A Bachelor degree from Australia or a recognised overseas institution. <br/> <br/>The following Defence members are eligible for direct entry into this course through the Veteran Tertiary Support Program - Postgraduate Course Entry: <br/> <br/>- Commissioned Officer (any rank), <br/>- Chaplain or Maritime Spiritual Wellbeing Officer, <br/>- Senior Non-Commissioned Defence Force Members (E-6 or higher), <br/>- Defence Force Members - Other Ranks (E-2 to E-5) with three or more years'''' experience.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/841AA/6/2027',
    updated_at = NOW()
WHERE cricos_course_code = '071683B';
UPDATE courses SET
    course_description = 'Your path to an exciting career in communication <p>Are you interested in advertising, public relations, journalism or media and arts production? Are you an international student? If so, our Diploma of Communication is the perfect pathway to many exciting careers.</p> By studying our Diploma of Communication you will: <ul> <li>be supported in building language and academic skills for further studies</li> <li>get direct entry to the 2nd year of a many bachelors degrees</li> <li>develop a good understanding in key cultural areas</li> <li>develop the professional expertise to enter and confidently contribute to the communication industries.</li> </ul> Study opportunities <p>Upon finishing your Diploma of Communication you can directly enter into one of the following courses delivered by the Faculty of Arts and Design, with one year of credit!</p> <ul> <li>Bachelor of Arts (Creative Writing)</li> <li>Bachelor of Arts (Cultural Heritage)</li> <li>Bachelor of Arts (Digital Media)</li> <li>Bachelor of Arts (Film Production)</li> <li>Bachelor of Arts (Global Studies)</li> <li>Bachelor of Communication and Media (Journalism)</li> <li>Bachelor of Communication and Media (Corporate and Public Communications)</li> <li>Bachelor of Media (Marketing Communication)</li> <li>Bachelor of Communication and Media (Sport Media) </li> </ul> Important to know <ul> <li>It will take 2 terms or 8 months of full-time study.</li> <li>If English is your second language you will need an Academic IELTS of 5.5 or TOEFL equivalent.</li> </ul> <p><em>Note: UC College courses fees may differ – please visit our <a href="https://www.canberra.edu.au/uc-college/course-fees">Course Fees</a> page for more information.</em></p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Students are required to meet English Language requirements and general admission requirements to the University of Canberra College.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC College, Bruce, ACT</td> <td>UC College Trimester 1 </td> <td>01 March 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>UC College, Bruce, ACT</td> <td>UC College Trimester 2 </td> <td>28 June 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>UC College, Bruce, ACT</td> <td>UC College Trimester 3 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/951AA/6/2027',
    updated_at = NOW()
WHERE cricos_course_code = '062888G';
UPDATE courses SET
    course_description = '<p>The next available intake for the <strong>Bachelor of Nursing</strong> is Semester 1, 2027</p> Recognised and accepted in over 160 countries <p>If you’re passionate about helping others and considering a future in nursing, then UC’s Bachelor of Nursing course offers an outstanding industry and globally respected platform to launch your nursing career.</p> <p>This immersive and fully interactive course incorporates the latest national and international interactive teaching and online practice methods, while using innovative technological and medical equipment to simulate real-life scenarios.</p> <p>As part of this course, you’ll also undertake multiple clinical placement opportunities and gain valuable insight and experience across a broad range of healthcare service providers.</p> <p>Successful completion of this course will enable you to become a registered nurse in Australia, and upon graduation you’ll have the necessary skills, experience and qualifications to be recognised as a nursing professional all over the world.</p> <p>This three-year full-time course can also be studied part-time and is fully accredited by the Nursing and Midwifery Board of Australia (NMBA) through the Australian Health Practitioner Regulation Agency (AHPRA).<br/> </p> Study a Bachelor of Nursing at UC and you will: <ul> <li>Develop and apply nursing knowledge and skills to approach all interactions with empathy in a culturally safe, respectful manner where cultural understanding and reconciliation are valued, ensuring that everyone feels safe.</li> <li>Conduct nursing assessments to establish priorities and inform planning; provide skilful nursing interventions for people across the lifespan within the scope of a Registered Nurse and evaluate responses to determine effectiveness.</li> <li>Integrate sciences, appraise research and apply evidence and strength-based, best-practice approaches to think critically and inform safe clinical decision-making for quality person-centred nursing care.</li> <li>Implement culturally appropriate nursing care, integrating First Nations perspectives on health, connection to land and community.</li> <li>Demonstrate professional communication and therapeutic relationships that are consistent with ethical strengths-based approaches to person-centred nursing care and relevant legal frameworks that govern healthcare practice.</li> <li>Build and apply career-readiness, a clear professional identity and the skills, knowledge and personal attributes necessary to meet the Nursing and Midwifery Board of Australia Registered Nurse Standards for practice.</li> </ul> Work Integrated Learning (WIL) <p>WIL is a vital component of this course, and in the first semester, you will have the opportunity to participate in a ten-day placement to accurately gauge the realities of a career as a registered nurse. Over the next three years, you will be required to complete a minimum of 800 hours of clinical practice across a range of local and regional healthcare settings - including areas such as community care, mental health, aged care, medical and surgical care, rehabilitation, palliative care, operating theatre, emergency department (ED) and intensive care unit (ICU).<br/> <br/> Participating placement venues include: Canberra Hospital, North Canberra Hospital, Goulburn Base Hospital, and several additional private healthcare clinics in and around ACT, Sydney and regional New South Wales, e.g., Bega. <br/> <br/> A core component of the UC nursing coursework takes place within the simulated environment, where students have the opportunity to develop and hone clinical skills and behaviours in spaces that look and feel like the clinical environment. UC nursing students can expect to spend hours rehearsing and practicing together utilising a myriad of simulation trainers, manikins, emerging technology (such as AI and VR), and even actors as they prepare for clinical practice.<br/> </p> Career opportunities <p>This course leads directly into becoming eligible for registration as an Australian-qualified Registered Nurse (RN). Nursing is a diverse career, and a UC-trained RN can comfortably look for work in the hospital sector, private health care, primary health care, rural and remote health care and military support. An Australian RN qualification is also highly respected internationally and opens the door to numerous nursing employment opportunities overseas.</p> Course-specific information <p>The Bachelor of Nursing is fully accredited by the Nursing and Midwifery Board of Australia through the Australian Health Practitioner Regulation Agency.</p> <p><strong>Before undertaking any clinical experience, you must:</strong></p> <ul> <li>Provide your immunisation history.</li> <li>Apply for a National Police Check.</li> <li>Apply for Working with Vulnerable People registration.</li> <li>Undertake a tuberculosis (TB) screening test.</li> <li>Sign any required NSW Health forms.</li> <li>Hold First Aid and CPR qualifications.</li> </ul> Professional accreditation <p>Professionally accredited by the Australian Nursing and Midwifery Accreditation Council (ANMAC). Graduates are eligible to apply for registration with the Australian Health Practitioner Regulation Agency (AHPRA). <br/> <br/>This three-year full-time course can also be studied part-time and is accredited by the Nursing and Midwifery Board of Australia (NMBA) <a href="https://www.nursingmidwiferyboard.gov.au/">https://www.nursingmidwiferyboard.gov.au/</a> through the Australian Health Practitioner Regulation Agency (AHPRA) <a href="https://www.ahpra.gov.au/">https://www.ahpra.gov.au/</a> <br/> <br/>The Nursing and Midwifery Board of Australia has developed a set of registration standards that define the requirements that applicants, registrants or students need to meet to be registered. Core standards cover criminal history, English language skills, continuing professional development, recency of practice and professional indemnity insurance arrangements. The standards can be accessed via this link: <a href="https://www.nursingmidwiferyboard.gov.au/registration-standards.aspx">https://www.nursingmidwiferyboard.gov.au/registration-standards.aspx</a> </p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Due to high enrolment numbers in Semester 1 2026 - Bruce campus, applications for Semester 2 2026 - Bruce campus are now closed. The next available intake is Semester 1 2027. <br/> <br/>Note: Offers for Semester 2 - Bruce campus are released in March each year only if vacancies remain after the Semester 1 intake. <br/> <br/>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/> <br/>- Year 12 ATAR <br/> <br/>- other Australian Qualification <br/> <br/>- work experience <br/> <br/>- overseas qualification <br/> <br/> <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/> <br/>More information is available on the Get into UC page: <a href="http://www.canberra.edu.au/future-students/get-into-uc">http://www.canberra.edu.au/future-students/get-into-uc</a> <br/> <br/> <br/>English Language Requirements: <br/>There are non-standard English language requirements for admission to this course that must be met by all candidates. To be eligible candidates must demonstrate English language proficiency via one of the following: <br/> <br/>1) English Language Assessment Test results from one of the following English proficiency tests: <br/>- Academic IELTS score of 7.0 overall with minimum score of 7 in listening, reading and speaking and minimum score of 6.5 in writing; or <br/>- OET grade of B with minimum score of B in listening, reading and speaking and minimum score of C+ in writing; or <br/>- TOEFL iBT with an overall score of 94 with minimum score of 24 in listening, reading and writing and 23 in speaking; or <br/>- PTE Academic score of 66 overall with minimum score of 66 in listening, reading and speaking and minimum score of 56 in writing. <br/> <br/>Results will only be accepted from either: <br/>- One test sitting, or <br/>- A maximum of two sittings in a 12-month period only if below minimum scores are met: <br/> -- Academic IELTS minimum overall score of 7 in each sitting and no score in any component of the test(s) for either test sitting below 6.5; <br/> -- OET tested in all four components in each sitting and no score in any component of the test(s) for either test sitting is below C+; <br/> -- TOEFL iBT minimum total score of 94 in each sitting and no score in any of the test sitting sections below 20 for listening, 19 for reading, 24 for writing and 20 for speaking; <br/> -- PTE Academic minimum overall score of 66 in each sitting and no score in any of the communicative skills for either test sitting below 56. <br/> <br/>OR <br/> <br/>2) Primary Language Pathway having undertaken six years of primary &amp; secondary education taught &amp; assessed in English, including at least two years between years 7 &amp; 12 from one of the following recognised countries: Australia, Canada, New Zealand, Republic of Ireland, South Africa, United Kingdom, &amp; the USA. <br/> <br/></p> Additional admission requirements <p>Immunisations <br/>TB Screening <br/>National Police Check <br/>NSW Health forms <br/>Working With Vulnerable People <br/>First Aid/CPR <br/></p> Assumed knowledge <p>Mathematics - general (minimum - required) English (required) Biological Science (preferred) Chemistry (preferred) Psychology (recommended)</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>UC Sydney Hills, Castle Hill, NSW</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>UC Sydney Hills, Castle Hill, NSW</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Any Australian Higher Education Provider</b></p> <p> <a href="/credit/30722">Diploma in Nursing (HLT54115) (30722)</a> </p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/30778">Diploma in Nursing (HLT54115) (30778)</a> </p> <p> <a href="/credit/34868">Diploma of Nursing (HLT54121) (34868)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/34849">Diploma of Nursing (HLT54121) (34849)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/364JA/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '095076E';
UPDATE courses SET
    course_description = 'Learn to manage the business of IT <p>If you are interested in learning the science of business informatics within an organisation, combined with an in-depth understanding of the capabilities and limitations of information technology, then the UC Graduate Diploma of Business Informatics is the course for you.<br/> <br/> The course is particularly suited to those looking for a career as a business analyst and are keen to mediate between organisational units and the information technologies that support them.<br/> </p> <p>This flexible intermediate-level course will cover many of the core areas of the ‘Skills Framework for the Information Age’ at a professional level, with weekday evening classes offered to enable you to balance study with your other commitments.<br/> <br/> Through this course, you will develop a solid understanding of the intent and context of systems, as well as their nature and development and will go on to learn how to address issues of work practice and information needs and use them to align technical and human systems.<br/> <br/> After this course, you will be well-placed to launch a successful career in business informatics or to progress to further postgraduate study via the Master of Business Informatics, which is available by enrolling in additional units.</p> Study a Graduate Diploma in Business Informatics at UC and you will: <ul> <li>demonstrate an understanding of theoretical concepts and develop an appropriate set of data models for relational database implementation</li> <li>critically analyse complex business processes</li> <li>be able to derive advanced system models appropriately</li> <li>learn how to use international standard systems description paradigms and languages</li> <li>prepare and critically evaluate documents associated with project planning, monitoring, review and quality</li> </ul> Work Integrated Learning (WIL) <p> Work Integrated Learning is a strong focus of the UC Graduate Diploma in Business Informatics course. As such, you will have the opportunity to regularly connect with the world of professional practice via examination of practical scenarios and industry case studies. </p> <p> As part of this course, you will also be encouraged to tailor your learning around areas of specific interest or in line with your professional aspirations. </p> <p> In addition, internships are available as part of your range of elective units and students can apply to spend time within organisations such as PricewaterhouseCoopers (PwC), Fujitsu Australia, Birdsnest, the University of Canberra and more. </p> Career opportunities <p>The UC Graduate Diploma in Business Informatics is a senior-level course offering those serious about advancing their career in any of the following areas:</p> <ul> <li>IT security analyst</li> <li>Business analyst</li> <li>Systems analyst</li> <li>IT project manager</li> <li>ICT consultant</li> <li>Web developer</li> <li>IT systems test engineer</li> <li>Information analyst</li> <li>Systems architect</li> <li>IT auditor</li> </ul> Course-specific information <p>A clear pathway of study exists between this degree and the Master of Business Informatics course. Students who have completed this course may apply and receive credit for units within the Master of Business Informatics.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Applicants must have a bachelor''''s degree in a non-IT field or equivalent. <br/> <br/>The following Defence members are eligible for direct entry into this course through the Veteran Tertiary Support Program - Postgraduate Course Entry: <br/> <br/>- Commissioned Officer (any rank), <br/>- Chaplain or Maritime Spiritual Wellbeing Officer, <br/>- Senior Non-Commissioned Defence Force Members (E-6 or higher), <br/>- Defence Force Members - Other Ranks (E-2 to E-5) with three or more years'''' experience.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/844AA/6/2027',
    updated_at = NOW()
WHERE cricos_course_code = '071684A';
UPDATE courses SET
    course_description = 'Let your career in the music industry take the stage <p>Turn your love of music into your career with a Bachelor of Creative Industries (Contemporary Music Practice). Delivered in partnership with TAFE Queensland, this innovative degree will give you a thorough grounding in the latest contemporary music practice. You''''ll develop high-level skills and knowledge in composition and song writing, performance, music production, technology, and theory. You''''ll collaborate with game designers, filmmakers, visual artists, actors, and other teams across the creative industries, working on real projects. With a focus on hands-on-learning and a holistic approach to what constitutes a modern portfolio career, you''''ll be prepared with the best chance of success in the new music industry.</p> <p>Complete your degree at our TAFE Queensland Brisbane campus where you''''ll build the foundations of your career and upon graduation, you''''ll be ready to jump into a career, anywhere you choose. </p> <br/> Study a Bachelor of Contemporary Music Practice at UC and you will: <ul> <li>Develop a broad range of coherent, specialised skills and knowledge that will make you stand out in this competitive, global industry. </li> <li>Gain a thorough grounding in 21st century contemporary music practice.</li> <li>Learn a broad range of skills and knowledge across a variety of areas including music composition, performance, technology and theory.</li> <li>Have the opportunity to collaborate with film makers, musicians, visual artists, actors, and other teams across the broad creative industries spectrum, working on real projects to combine university thinking with hands-on learning.</li> </ul> <p>With a focus on nurturing and developing a holistic, creative and entrepreneurial approach to music making, you''''ll be prepared with the best chance of success in the music industry.</p> Work Integrated Learning <p>You’ll be encouraged and supported to find relative work placements, enabling you to experience the reality of working within the industry or a particular company, and the opportunity to build useful networks for a future career. </p> Career opportunities <ul> <li>Sound Engineer</li> <li>Composer</li> <li>Music Producer</li> <li>Musician</li> <li>Music Teacher</li> <li>Music Arranger</li> <li>Songwriter</li> <li>Vocalist</li> <li>Sound Engineer</li> </ul> Course Specific information <p>Standard entry to this program is by audition only.</p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank and audition outcome. An entrance rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- diploma pathway <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>Applicants who meet the minimum entrance rank will be required to complete an audition as part of the admission process. Applicants are expected to undertake the audition at the date and time allocated to them. Full details regarding the audition process will be provided in the offer letter. <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/> <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>Audition</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>South Bank, QLD</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Coomera, QLD</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Coomera, QLD</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>South Bank, QLD</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Music Industry College Pty Ltd</b></p> <p> <a href="/credit/27774">Diploma of Music (27774)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/26553">Diploma of Music (26553)</a> </p> <p><b>Tafe Queensland</b></p> <p> <a href="/credit/33747">Diploma of Music Industry (33747)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB403/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '102457G';
UPDATE courses SET
    course_description = 'Forge a career in Fashion <p>Unleash your creativity with a degree in Applied Fashion. Thanks to our partnership with TAFE Queensland, you’ll gain all the knowledge, skills, and the right vocabulary you need to succeed in the competitive world of fashion. Break into the creative industry and pursue a career you’re passionate about and benefit from our hands-on approach to learning and innovative teaching. If you have a keen eye for detail and want to develop your skillset in research, design, manufacturing, and pattern cutting then this course is for you. Get experienced in a wide variety of market levels, from couture to high street, through a range of projects, many of which are in sponsored by specific labels or companies. </p> <p>Complete your degree at our TAFE Queensland Brisbane campus where you''''ll build the foundations of your career and upon graduation, you''''ll be ready to jump into a career, anywhere you choose. </p> Study a Bachelor of Applied Fashion at UC and you will: <ul> <li>Add flair to your career in fashion with this hands-on degree and develop a broad range of advanced technical and creative skills. </li> <li>Engage in holistic creative projects and learn problem solving and analytical tasks which will prepare you to work within the industrial, social and cultural creation frameworks needed to build a career in this dynamic field.</li> <li>Develop fashion concepts and communicate those concepts through cutting edge visual artefacts, and produce fashion items within well-articulated design briefs. </li> <li>Graduate with advanced technical skills in fashion design and manufacturing, alongside theoretical understandings of how the fashion systems work. </li> </ul> Work Integrated Learning <p>You’ll be encouraged and supported to find relative work placements, enabling you to experience the reality of working within the industry or a particular company, and the opportunity to build useful networks for your future career. </p> Career opportunities <ul> <li>Fashion Coordinator</li> <li>Fashion Designer</li> <li>Production Manager</li> <li>Retail Buyer</li> <li>Stylist</li> <li>Textile Designer </li> <li>Merchandising Assistant</li> <li>Patternmaker </li> <li>Tailor</li> </ul> Course Specific information <p>Standard entry to this program is by interview and portfolio only.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- diploma pathway <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/> <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>None.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Mount Gravatt, QLD</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Mount Gravatt, QLD</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>National Institute Of Education And Technology</b></p> <p> <a href="/credit/28333">Diploma of Applied Fashion Design and Merchandising (28333)</a> </p> <p><b>Tafe Queensland</b></p> <p> <a href="/credit/33866">Diploma of Applied Fashion Design &amp; Merchandising - MST50122 (33866)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB402/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '102456H';
