UPDATE courses SET
    course_description = 'Forge a career in the international development space <p>This pioneering course explores the latest theories on sustainable development and cross-cultural practice, in relation to issues such as poverty, empowerment and gender. You will intricately hone your practice-led research skills and be prepared for a rewarding career solving some of the most challenging problems facing the world today.</p> <p>Opportunities exist for graduates in a range of areas, including non-government organisations, the charity sector, public development agencies, multinational businesses, government agencies and academia. You can look forward to a successful career working with bodies like World Vision, Oxfam, the Australian Red Cross, Save the Children, TEAR Australia and the Department of Foreign Affairs and Trade, among many others.</p> Study a Master of International Development at UC and you will: <ul> <li>acquire knowledge about development issues across the world, especially with under-privileged communities</li> <li>engage with contemporary development theory</li> <li>explore participatory approaches to planning, management, monitoring and the evaluation of development projects</li> <li>acquire knowledge and understanding of the politics of different aspects of development processes, practices and advocacy.</li> </ul> Work Integrated Learning <p>During the course you will have the opportunity to enrol in the Development Research Project unit which actively encourages students to explore a real-life development project in their thesis, and is often linked to their current employment. Master’s students have investigated actual global development projects in countries including Papua New Guinea, Indonesia, Mexico, Pakistan and more.</p> Career opportunities <ul> <li>International consultant</li> <li>Program director</li> <li>International aid worker</li> <li>Campaign director</li> <li>International project manager</li> <li>Head of fundraising</li> <li>International development worker</li> <li>Community development educator</li> <li>Gender adviser</li> <li>M&amp;E (monitoring and evaluation) manager</li> <li>Program specialist</li> <li>Program coordinator</li> <li>Program analyst</li> <li>Social impact assessment consultant</li> <li>Project manager</li> </ul> Study for less with Commonwealth Supported Places (CSP) <p>A course with Commonwealth Supported Places (CSP) means the Australian Government has subsidised a portion of your degree, reducing the total balance you are required to pay (known as the student contribution amount).<br/> The CSP amount is determined by the course you are undertaking and the industry you''''ll be working in after graduation.<br/> For more information on CSP, click <a href="https://www.canberra.edu.au/future-students/study-at-uc/fees-and-costs/domestic-fees-and-costs">here</a>. </p> Course-specific information <p>If undertaking the Development Research Project unit, students may be required to complete a Police Check.</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Applicants must have an undergraduate degree (AQF level 7) or equivalent as approved by the University Admissions. <br/> <br/>Applicants who have completed the Graduate Certificate in Academic Foundations (EDC201) are also eligible for entry. <br/> <br/>Students who have completed the Graduate Certificate in International Development may apply and receive credit for the 4 units (12 credit points) completed study under this degree. <br/> <br/>Students who have completed the Graduate Diploma in International Development can articulate into the Master''''s course with credit for the 8 units (24 credit points)completed under this degree. <br/> <br/>In making an offer to an applicant, the University will give consideration to a range of factors including English proficiency, academic record and/or employment experience. <br/> <br/>Applicants with a completed Bachelor''''s degree in a related/cognate field may be granted credit for up to 12 credit points of unspecified credit reducing the degree duration to 1.5 Years (EFTSL), additional credit from completed Graduate Certificate in International Development or Graduate Diploma in International Development may reduce this duration further. <br/> <br/>Defence Members who hold an equivalent rank of O-1 or above as an officer or chaplain, or E06 and above as an SNCO, are eligible for direct entry into this Masters degree as part of the Veteran Tertiary Support Program. <br/> <br/>You can use professional experience and prior learning to enter into a postgraduate qualification at UC through our Professional Pathway Entry program. If you have significant work experience or hold industry-recognised qualifications, this program could be your route to bypass undergraduate study and accelerate your career. Explore Professional Pathway Entry <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry">https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/193JA/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '074938D';
UPDATE courses SET
    course_description = '<strong>Kick-start your career in health</strong> <p>Are you interested in pursuing a career in health? Our Diploma in Health at the University of Canberra is designed as a pathway into a range of health-related degrees, including Health Science, Psychology, Human Movement and Human Nutrition. In this course, students develop technical and theoretical knowledge across a broad range of health areas, alongside critical analysis, problem-solving, communication and collaboration skills. With a variety of employment opportunities available in both health and community organisations, studying a Diploma in Health will provide you with the skills to succeed in an ever-valuable industry.</p> <strong>Study opportunities</strong> <p> On finishing your diploma, you can enter directly into the second year of a: </p> <ul> <li>Bachelor of Health Science</li> <li>Bachelor of Health Science (Human Movement)</li> <li>Bachelor of Human Nutrition</li> <li>Bachelor of Science in Psychology</li> </ul>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Students are required to meet English Language requirements and general admission requirements to the University of Canberra College.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2028</td> <td>UC College, Bruce, ACT</td> <td>Semester 1 </td> <td>14 February 2028</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2028</td> <td>UC College, Bruce, ACT</td> <td>Semester 2 </td> <td>07 August 2028</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/358JA/5/2028',
    updated_at = NOW()
WHERE cricos_course_code = '090071F';
UPDATE courses SET
    course_description = 'Open an insightful and intellectually stimulating world of professional possibilities <p>If you’re a deep thinker with your finger on the political pulse and interested in pursuing a career of exploration and change, then this is the course for you. UC’s Bachelor of Politics and International Relations/Bachelor of Science in Psychology double degree combines the intriguing world of politics and international affairs with the clinical psychological insights to human behaviour of a psychology degree.</p> <p>You’ll develop the knowledge and skills to become a globally engaged and strategic thinker while discovering the scientific psychology theories, research methods and clinical grounding that could help you become a clinical psychologist.</p> <p>Your psychology studies will be accredited by the Australian Psychology Accreditation Council (APAC) and the Australian Psychological Society (APS) and give you a solid grounding in topics like cognition, psychopathology and biological behaviour, and the tools to instigate practical solutions to problems within various social and economic contexts – skills that could also come in handy should you choose to pursue a career in politics and international relations.</p> Combine a Bachelor of Politics and International Relations and a Bachelor of Science in Psychology at UC and you will: <ul> <li>gain knowledge of the principles, concepts and issues that are shaping the world, including the challenges of modern terrorism and contemporary regional politics in the Asia-Pacific region and beyond</li> <li>be able to apply an in-depth understanding of the historical and current systems of Australian politics and public policy, provide policy advice and develop new policies</li> <li>learn to recognise the relationships between political values, political power and public policy and the impact each of these has within the Australian context</li> <li>develop high level theoretical and empirical analysis skills and the ability to interpret world events and issues</li> <li>acquire an understanding of the scientific basis of the discipline of psychology and understand the research methods used by psychologists</li> <li>gain an ability to apply research methods to design and conduct studies, analyse and interpret results and write research reports using APAC conventions</li> <li>understand the application of values, research and professional ethics in psychological research and in other professional contexts.</li> </ul> Career opportunities <p>The world is your oyster! Diplomat, policy adviser, intelligence analyst, psychologist or even politician… your career options (and the potential to earn a healthy salary and travel) will be endless with UC’s Bachelor of Politics and International Relations/Bachelor of Laws degree. Graduates will have the accredited skills and qualifications required to explore careers in:</p> <ul> <li>diplomacy</li> <li>including strategic analysis, trade relations and foreign affairs</li> <li>intelligence, including security analysis</li> <li>international business and aid</li> <li>the public sector, including policy development</li> <li>politics</li> <li>the not-for-profit sector</li> <li>clinical psychology</li> <li>counselling</li> <li>private practice</li> <li>media, communications, public affairs and public relations</li> <li>domestic or international business, including consultancy</li> <li>management</li> <li>education and research.</li> </ul> Professional accreditation <p>The Bachelor of Science in Psychology is accredited by the Australian Psychology Accreditation Council (<a href="https://apac.au/">https://apac.au/</a> )</p> Professional accreditation <p>The Bachelor of Science in Psychology is accredited by the Australian Psychology Accreditation Council (<a href="https://apac.au/">https://apac.au/</a> )</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>For Work Integrated Learning (WIL) in Psychology, students may require a Working with Vulnerable People card.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 <a href="#"></a></td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 <a href="#"></a></td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/SCSC03/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '095939G';
UPDATE courses SET
    course_description = '<p> The Graduate Certificate in Business is designed to introduce you as managers and aspiring leaders to the core functions of management and business administration. The course focuses on the core business skills of decision making and problem solving within a complex business environment. The Graduate Certificate in Business provides theoretical knowledge combined with the practical skills to manage existing organisations or start new businesses. </p>',
    

    entry_requirements = '<p>Applicants must have a bachelor qualification or equivalent in any field OR three years'''' relevant work experience.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 1 </td> <td>18 January 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 2 </td> <td>15 March 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 3 </td> <td>10 May 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 4 </td> <td>05 July 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 5 </td> <td>30 August 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 6 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/MGC103/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '085113K';
UPDATE courses SET
    course_description = 'Build your future in Software Engineering. <p>If you''''re aiming to become a skilled, in-demand software engineer, UC''''s Bachelor of Software Engineering is your launchpad. Gain the hands-on experience, technical expertise and industry connections you need to design and build the software shaping our world.</p> Why study Software Engineering at UC? <p>This course is designed to help you think like an engineer and work like a developer. You’ll gain a solid foundation in computer science, along with advanced skills in database design, programming, coding and systems analysis. You’ll also sharpen your communication and critical thinking abilities, which are key to delivering effective, real-world software solutions.</p> <p>You’ll become fluent in core programming languages and learn to engineer software using leading methodologies like UML, XML, and structured systems approaches. Build and test your creations across environments, including Windows, Linux, mobile and cloud computing.</p> Tailor your learning: <p>UC''''s Bachelor of Software Engineering gives you the flexibility to specialise in areas that align with your career goals, including:</p> <ul> <li>Robotics and AI</li> <li>Cybersecurity and System Administration</li> <li>Data Science</li> <li>Cloud Computing and IoT</li> </ul> Learn through experience with Work Integrated Learning (WIL) <p>Work Integrated Learning is a core part of this degree. Across your studies, you''''ll engage with real industry clients, projects and placements, building both your resume and your confidence.</p> <p>Our strong industry connections mean you''''ll have access to a wide network of partners, with previous internships at:</p> <ul> <li>Xero Australia</li> <li>Fujitsu Australia</li> <li>Australian Taxation Office (ATO)</li> <li>Intelledox</li> <li>Pursuit Technology</li> <li>Birdsnest</li> <li>ThoughtPatterns Consulting</li> <li>HydroAlgorithmics</li> <li>and many more.</li> </ul> Career opportunities and outcomes <p>Graduates of the Bachelor of Software Engineering are highly employable, industry-ready and equipped to work across a wide range of sectors. With strong technical foundations, practical experience and a recognised qualification, you''''ll stand out in the job market and be ready to launch a career in roles such as:</p> <ul> <li>Software engineer</li> <li>Cloud computing architect</li> <li>Software and games developer</li> <li>ICT project manager</li> <li>ICT security specialist</li> <li>IoT engineer, developer or designer</li> <li>Cybersecurity specialist</li> <li>Service desk manager</li> <li>System administrator</li> <li>Cybersecurity operations manager</li> <li>Big data engineer</li> <li>Big data architect</li> <li>Data scientist</li> <li>Business intelligence specialist</li> <li>Artificial intelligence engineer</li> <li>Machine learning engineer</li> <li>Robotics specialist.</li> </ul> Course-specific information <p>This course is accredited by the Australian Computer Society (ACS) at the Professional level. High-achieving students may be eligible to enrol in Honours in Information Sciences, and there are clear pathways from this course to the Master of Information Sciences (Research) and other postgraduate degrees.</p> Professional accreditation <p>This course is accredited by the professional body, the Australian Computer Society, at the Professional level.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>Basic knowledge and skills in ICT (Information and Communication Technology); Basic numeracy and literacy skills. </p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Winter Term </td> <td>07 June 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/35549">ICT40120 Certificate IV in Information Technology &amp; ICT50220 Diploma of Information Technology (35549)</a> </p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/35588">ICT40120 Certificate IV in Information Technology (35588)</a> </p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Hunan University</b></p> <p> <a href="/credit/34027">Study in Engineering Program (34027)</a> </p> <p><b>Melbourne College Of Advanced Studies</b></p> <p> <a href="/credit/31864">Bachelor Qualifying Program (BQP) Business Course (Completion of two semester''''s study) (31864)</a> </p> <p> <a href="/credit/32026">Bachelor Qualifying program (BQP) Science-IT Course (completion of two semester''''s study) (32026)</a> </p> <p><b>Melbourne College Of Advanced Studies</b></p> <p> <a href="/credit/31964">Bachelor Qualifying Program (BQP) Engineering Course (Completion of two semesters''''s study) (31964)</a> </p> <p><b>Melbourne College Of Advanced Studies</b></p> <p> <a href="/credit/31827">Bachelor Qualifying Program (BQP) Business Course (Completion of one semester''''s study) (31827)</a> </p> <p> <a href="/credit/31905">Bachelor Qualifying Program (BQP) Engineering Course (Completion of one semester''''s study) (31905)</a> </p> <p><b>Melbourne College Of Advanced Studies</b></p> <p> <a href="/credit/32005">Bachelor Qualifying Program (BQP) Science-IT Course (completion of one semester''''s study) (32005)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><b>University Of Canberra College</b></p> <p> <a href="/credit/31744">Diploma of Information Technology (31744)</a> </p> <p><a href="#">See more</a></p>',
    apply_form = 'https://www.canberra.edu.au/course/560AA/8/2027',
    updated_at = NOW()
WHERE cricos_course_code = '054017M';
UPDATE courses SET
    course_description = '<p>The Graduate Diploma in Law is a postgraduate law program designed for those who have completed or are close to completing a bachelor''''s degree in a non-law discipline to enhance their qualifications through graduate legal studies. Students tailor their individual program of study to their needs by studying two foundation units and six electives, including subject streams such as business law and public policy streams.</p> <p>Students may transition to the Juris Doctor (JD), which is a master''''s level pathway to legal practice throughout Australia with professional accreditation with the Supreme Court of the ACT and the State of New South Wales (the Graduate Diploma is not itself a qualification to practice law). With an emphasis on practical legal problem-solving, the JD units are designed to ground legal education in the broader social and economic context and support students'''' development as ethical professionals.</p> <p>With small class sizes and highly qualified and experienced staff, students are encouraged to develop their advocacy abilities and legal skills. Students who transition to a JD will apply their skills in the workplace, with opportunities to complete an extended practical research project or law internship through linkages with law firms, government and non-government agencies and overseas universities.</p> Study a Graduate Diploma in Law at UC and you will: <ul> <li>Study foundational legal units</li> <li>Develop practical dispute resolution skills </li> <li>Understand and apply the theory and history of law</li> <li>Discover how the law engages with and shapes disruptive technologies </li> </ul> Career outcomes: <p>With a Graduate Diploma in Law from the University of Canberra, you will be building your legal knowledge to apply in a variety of work settings. If you continue to study the Juris Doctor, your career options include working as a:</p> <ul> <li>Solicitor</li> <li>Legal counsel</li> <li>Workplace relations consultant</li> <li>Family lawyer</li> <li>Legal case manager</li> </ul> <p><em>A third of people employed in a legal profession have a postgraduate qualification (source: Job Outlook).</em></p>',
    

    entry_requirements = '<p>Applicants must have an undergraduate degree (or equivalent) in any non-law discipline, with a GPA of at least 5/7.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 1 </td> <td>18 January 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 2 </td> <td>15 March 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 3 </td> <td>10 May 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 4 </td> <td>05 July 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 5 </td> <td>30 August 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 6 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/SCG003/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '040756B';
UPDATE courses SET
    course_description = 'Master your proficiency in education <p>If you are an Education graduate looking to take your career to the next level, this one-year postgraduate course will provide you with a deepened knowledge of the issues affecting modern education. You will explore areas including contemporary theory, critical research and the effects of globalisation on the reconfiguring of the education sector.</p> <p>Engaging and flexible, the course can be taken either full-time or part-time, and tailored to meet your individual professional needs, with your study culminating in the presentation of a substantial piece of scholarship. You will be required to offer an evidence-based analysis on a topic relevant to your field of practice which you will then present as part of a group-based capstone unit. Upon graduation, you will be well-positioned for additional postgraduate education study, career progression within your own workplace, or ready to succeed in a new role as a senior education professional.<br/> </p> Study a Master of Education at UC and you will: <ul> <li>understand the contemporary developments that have an impact across a variety of professional practice fields in education.</li> <li>examine the globalised character of educational theory, curriculum development, policy and practice.</li> <li>develop the capacity to analyse and critique professional knowledge.</li> <li>analyse how globalisation''''s interdependent economic, political, cultural and technological dimensions affect education.</li> <li>review research perspectives and practices in the social sciences and humanities, with particular reference to education and communication.</li> </ul> <br/> Work Integrated Learning <p>This course has been developed with Work Integrated Learning (WIL) at its core. The content has been created by education professionals, and kept relevant and up-to-date through consistent monitoring of, and engagement with, the industry. You will undertake authentic assessment tasks which are highly relevant to the day-to-day practice of education, dealing regularly with real-world problems and case studies, and will be encouraged to apply course learnings to your own educational employment context.</p> Career opportunities <ul> <li>Principal</li> <li>Deputy principal</li> <li>Head of department</li> <li>Executive teacher</li> <li>Year adviser</li> <li>Schools policy adviser</li> <li>Educational policy developer</li> <li>Curriculum developer</li> <li>Corporate trainer</li> <li>Higher education researcher</li> <li>Vocational education and training instructor</li> <li>Education assessment specialist<br/> </li> </ul> Course-specific information <p><strong>To apply for this course, students must have:</strong></p> <ul> <li>a four-year undergraduate degree in education or a three-year undergraduate degree plus a one-year Graduate Diploma in Education, and in either case a minimum of three years’ professional experience in an educational context; OR </li> <li>a three-year undergraduate degree in education or a cognate discipline deemed equivalent by the University’s Admissions Committee, and in either case a minimum of four years’ professional experience in an educational context.</li> </ul> <p>This course is not externally accredited and, therefore, it is not recognised as a teaching qualification in Australia. If you are looking to transition into a teaching career, UC offers a selection of suitable postgraduate courses.</p> <p>A clear pathway of study exists between the Graduate Certificate in Education and this degree. Students who have completed the Graduate Certificate in Education may apply and receive credit for units within the Master of Education.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>A four-year undergraduate degree in education or a three-year undergraduate degree plus a one-year graduate diploma in education, and in either case a minimum of three years professional experience in an educational context; <br/>OR <br/>A three-year undergraduate degree in education or a cognate discipline deemed equivalent by the University Admissions Committee, and in either case a minimum of four years professional experience in an educational context.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2026</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>16 February 2026</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2026</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>10 August 2026</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/EDM103/1/2026',
    updated_at = NOW()
WHERE cricos_course_code = '114239G';
UPDATE courses SET
    course_description = 'The gateway to your career as a clinical psychologist <p>Welcome to the UC Master of Clinical Psychology course, an intensive two-year academic journey that will provide you with rigorous professional training and equip you with the skills and knowledge to become a registered clinical psychologist.</p> <p>Through a mix of advanced coursework, supervised practicum placements, and a research project on a topic of clinical relevance, you will acquire in-depth assessment, evaluation, and intervention skills readying you to work as a practicing psychologist.</p> <p>On enrolment, you will be registered as a provisional psychologist and then go on to complete up to 1000 hours of supervised practical placements. The first two placements will be in the University’s student-led Health Clinic, where you will gain exposure to inter-professional practice with additional training opportunities occurring in workplace settings, always under the support and supervision of experienced academic mentors.</p> Study a Master of Clinical Psychology at UC and you will: <ul> <li>Use your knowledge of psychology and mental health to critically assess, diagnose, develop case formulations, treat and prevent psychological problems and mental health issues across the lifespan.</li> <li>Understand your profession concerning the unique role of clinical psychologists in providing evidence-based psychological services, including assessment, diagnosis, treatment, research and consultancy services across diverse settings.</li> <li>Understand psychopathology, psychopharmacology and psychological medicine, and neurological issues relevant to mental health presentations, diagnostic systems, health psychology and behavioural medicine.</li> <li>Transform research and evaluation findings into policy, applied knowledge and improved treatments.</li> <li>Provide competent expert oral and written reports to various stakeholders on psychological matters for health, medical, medico-legal and forensic purposes.</li> <li>Competently work within a cross-cultural context.</li> <li>Practice with children, adolescents, adults and older persons in a manner relevant to Clinical Psychology.</li> <li>Conduct high-level, advanced independent research on a topic of clinical relevance.</li> </ul> Work Integrated Learning <p>During this course, you will undertake four practical placements, totaling 1,000 hours. The first two placements will be in the student-led clinic on campus and take place in a range of settings, including working with children, adolescents, adults, and older people, and in a variety of organisations. In each situation, you will develop your competencies as a clinical psychologist by working with clients under supervision.</p> Career opportunities <p>Career opportunities for Clinical Psychologists are considerable, and UC graduates are in high demand across a wide range of services within the public and private such as:</p> <ul> <li>Private practice supporting members of the public.</li> <li>Health departments, hospitals and community practices.</li> <li>National, state or local government or non-government organisations.</li> <li>Welfare agencies, educational institutions, defense, justice and community services.</li> </ul> Course-specific information <p>To be eligible for consideration for the UC Master of Clinical Psychology program, you must be able to provide evidence of completing a four-year sequence in psychology within the last ten years - with accreditation by the Australian Psychology Accreditation Council (APAC) or equivalency as determined by the Australian Psychological Society (APS). </p> <p>This requirement is necessary to ensure eligibility for provisional registration with the Australian Health Practitioners Regulation Agency (AHPRA) and Associate Membership of the APS and the Australian Clinical Psychology Association (ACPA).</p> <p>Shortlisted applicants will be required to attend an on-campus interview, which will help determine your eligibility.</p> <p>Provisional registration with AHPRA will also require a federal police clearance, and all relevant immunisations must be up to date before participating in any work placements.<br/> Some placement organisations may also require a current Working with Vulnerable People clearance.</p> <p><a href="http://go.canberra.edu.au/rs/228-BKB-088/images/2025 Course Handbook.pdf?version=0">Master of Clinical Psychology Handbook 2025</a></p> Professional accreditation <p>The Master of Clinical Psychology covers the Levels 3 and 4 graduate competencies set by the Australian Psychology Accreditation Council (APAC <a href="https://apac.au/">https://apac.au/</a> ) and is an accredited postgraduate training program. Upon completion graduates to be eligible for general registration as a psychologist and entry into the registrar program for the Clinical Psychology Area of Practice Endorsement through AHPRA. The course also meets the requirements for membership of the Australian Psychological Society (APS), Associate membership of the APS College of Clinical Psychologists, and membership for the Australian Clinical Psychology Association (ACPA).</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Applicants must meet all of the following criteria: <br/> <br/>1. Completion of a four-year APAC accredited sequence in psychology, typically an honours degree, within the last 10 years with a minimum GPA of 75% in the 4th year (honours or graduate diploma); and <br/> <br/>2. be eligible for, or hold, provisional registration as a psychologist with AHPRA <br/> <br/>Domestic applications open on the 2nd September and close on the 15th October each year for the following year. Domestic applicants must apply through the Universities Admissions Centre (UAC) <a href="http://www.uac.edu.au/postgraduate/">http://www.uac.edu.au/postgraduate/</a> <br/> <br/>International (offshore) applications open on the 1st August and close on the 30th August each year for the following year. <br/> <br/>International (onshore) applications open on the 1st August and close on the 15th October each year for the following year. <br/> <br/>Referee reports must be submitted through the Psychology Reference Portal <a href="https://psychologyreference.zendesk.com/">https://psychologyreference.zendesk.com/</a> Applicants must ensure they share the reference with the University of Canberra. If the reference is not shared we cannot access the referee reports and the application will be deemed incomplete and the application will not be processed further. <br/> <br/>Limited Commonwealth-supported places (CSPs) are available for this course and will be awarded on academic merit. Eligible applicants who are not given a CSP will be recommended for fee-paying (FEE) places.</p> Additional admission requirements <p>Applicants must also provide: <br/> <br/>- a current Curriculum Vitae (CV), and <br/> <br/>- two referee reports submitted through the Psychology Reference Portal <a href="https://psychologyreference.zendesk.com/">https://psychologyreference.zendesk.com/</a> <br/> <br/> <br/>Shortlisted applicants (domestic and international) will be required to attend an interview in which their suitability for clinical practice will be assessed. Interviews are preferably attended in person (on campus). Requests for an online interview can be submitted in special circumstances for consideration or when applicant is located offshore. The time and date of the interview is unfortunately not negotiable, due to the tight scheduling requirements. <br/> <br/> <br/>NOTE <br/> <br/>Above requirements are the minimum standard and not negotiable. Entry is competitive and places limited. Shortlisting for interview is determined against the applicant''''s academically ranked place in the applicant list, and the referee reports. Work experience in related areas as well as local knowledge and commitment will be used as part of the ranking process. The thresholds for interview considerations vary each year in response to characteristics of the applicant pool. It is emphasised that meeting the minimum entrance requirements does not of itself guarantee an interview. Please note that it is the applicant''''s responsibility to ensure that UAC and UC have the correct and most current information against which applications are assessed.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 1 </td> <td>25 January 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/742AA/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '049512E';
UPDATE courses SET
    course_description = 'Create a career you’ll love in Visual Arts <p>Turn your love of Art into your career with a Bachelor of Creative Industries (Visual Arts). Thanks to our partnership with TAFE Queensland, you’ll learn traditional skills and techniques to ground your understanding of contemporary culture historically and theoretically. </p> <p>Explore contemporary arts interfaces with digital technologies and expand into cross media, multi-disciplinary visual arts practice. You’ll look at different genres of arts practice, art communities, curating, design/commercial opportunities, and contemporary visual identities. All of this combined will ensure you graduate job-ready with the connections to dive right into the Arts industry. </p> <p>Complete your degree at our TAFE Queensland Brisbane campus where you''''ll build the foundations of your career and upon graduation, you''''ll be ready to jump into a career, anywhere you choose. </p> <br/> Study a Bachelor of Visual Arts at UC and you will: <ul> <li>Develop a broad and coherent range of specialist knowledge and practical skills. </li> <li>Gain hands-on skills and techniques to build your abilities and understanding of contemporary art and culture.</li> <li>Explore contemporary arts and expand into cross media, and multi-disciplinary visual arts practices.</li> </ul> <p>Graduates can develop their careers in a wide range of art, design, and culturally related fields including gallery exhibitions, arts education, arts administration, curating, exhibition, display design, public art and more.</p> Work Integrated Learning <p>You’ll be encouraged and supported to find relative work placements, enabling you to experience the reality of working within the industry or a particular company, and the opportunity to build useful networks for a future career. </p> Career opportunities <ul> <li>Arts Professional </li> <li>Art Curator</li> <li>Photographer </li> <li>Illustrator </li> <li>Graphic Designer</li> <li>Product Designer</li> </ul> Course Specific information <p>Standard entry to this program is by interview only</p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- diploma pathway <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/> <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>None.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>South Bank, QLD</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>South Bank, QLD</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Tafe Queensland</b></p> <p> <a href="/credit/26735">Diploma of Visual Arts - CUA51120 (26735)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB405/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '102459E';
UPDATE courses SET
    course_description = 'Shape your career in IT with the help of UC <p>If you’re considering a move into a career in ICT but are concerned that your lack of knowledge and experience in this field will hinder your career prospects, relax - this course has everything you need to forge a successful career in IT – fast!</p> <p>No matter what your background, this course has been designed around those with no formal study or employment background in IT.<br/> In this course, you will get to explore the key areas of the ‘Skills Framework for the Information Age’ and gain a comprehensive understanding of software technology and engineering practice.</p> <p>Highly flexible, this course also covers the fine details of database design and engineering management and offers a variety of delivery modes to help you balance your study with other commitments, including weekday classes during business hours and in the evenings.</p> <p>As part of UC’s commitment to Work Integrated Learning (WIL), you will also get the opportunity to undertake an internship within a professional organisation, which will help you gain necessary practical skills and improve your chances of securing your ideal IT job.</p> <p>This course offers the chance to specialise in either Artificial Intelligence and Machine Learning, Cloud Computing, Cybersecurity, Data Science, IoT &amp; Robotics Network Technologies and Project Management.</p> Study a Master of Information Technology and Systems at UC and you will: <ul> <li>gain an introduction to software technology and engineering practice</li> <li>be brought up to speed with the latest industry processes and strategies</li> <li>learn about security, support and operating a quality, professional IT practice</li> <li>be able to choose from a range of relevant specialisations</li> <li>study information technology and systems in the workplace</li> <li>cover key contemporary IT issues</li> <li>gain exposure to top-level industry contacts</li> <li>possess the skills to confidently pursue a career in IT</li> <li>gain a globally recognised qualification.</li> </ul> Work Integrated Learning (WIL) <p>WIL is an integral component of the UC Master of Information and Technology course as it offers students the opportunity to gain valuable hands-on experience and build professional relationships through real work, or work-like placements.</p> <p>To ensure our students have access to the right people and places, UC works hard to foster close industry connections and regularly engages with industry partners who possess both the skills and experience to provide specialised knowledge and training opportunities.</p> <p>All course content is reviewed annually by our Course Advisory Group, which is made up of a panel of highly qualified and respected industry experts.</p> Career opportunities <p>The UC Master of Information Technology and Systems is a globally recognised and industry-respected qualification that is designed to help you secure a career in any of the following areas:</p> <ul> <li>Network manager</li> <li>Cybersecurity specialist</li> <li>Programmer</li> <li>Web and mobile developer</li> <li>Business and systems analyst.</li> </ul> Course-specific information <p>Applicants need to have completed an Australian bachelor’s degree in any field or equivalent, be fluent in the use of a desktop computer, and have excellent English spoken and written communication skills. No previous IT knowledge is assumed.</p> <p>This course is fully accredited by the Australian Computer Society, at the Professional level.<br/> A clear pathway of study exists between this degree, the Graduate Certificate in Information Technology and the Graduate Diploma in Information Technology.</p> Professional accreditation <p>Full accreditation at Professional Level with the Australian Computer Society.</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>An Australian bachelor degree in any field or equivalent. <br/> <br/>You can use professional experience and prior learning to enter into a postgraduate qualification at UC through our Professional Pathway Entry program. If you have significant work experience or hold industry-recognised qualifications, this program could be your route to bypass undergraduate study and accelerate your career. Explore Professional Pathway Entry <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry">https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry</a> </p> Assumed knowledge <p>Proficiency in using computers.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2028</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>14 February 2028</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2028</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>07 August 2028</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Henan University Of Engineering</b></p> <p> <a href="/credit/34669">B Computer Science and Technology OR Software Engineering OR Data Science (HUE) + ITB101 (UC) (34669)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/973AA/7/2028',
    updated_at = NOW()
WHERE cricos_course_code = '064327C';
UPDATE courses SET
    course_description = '<p> The Graduate Certificate in Business Administration (Government) is designed to introduce you as managers and aspiring leaders to the core functions of management and business administration within the government context. The course develops your knowledge of legal frameworks, the policy process and strategic communication, and also explores the theory and practice of government procurement. Designed for those working within government or government-focused organisations, this course offers a foundational pathway to management and leadership roles and for advanced professional studies. </p>',
    

    entry_requirements = '<p>Applicants must have a bachelor qualification or equivalent in any field OR three years'''' relevant work experience.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 1 </td> <td>18 January 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 2 </td> <td>15 March 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 3 </td> <td>10 May 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 4 </td> <td>05 July 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 5 </td> <td>30 August 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>UC - Canberra, Online</td> <td>Study Block 6 </td> <td>25 October 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/MGC102/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '071683B';
UPDATE courses SET
    course_description = 'Your future in Sonography awaits <p>The only course of its type in Australia, the Graduate Certificate in Ultrasound Studies is the first step on your pathway to a career in sonography.</p> <p>This course is suited to graduates from any Bachelor’s degree inclusive of human anatomy and physiology units and is designed to develop practical skills and principal knowledge in sonography. These skills will support you in securing the industry placement necessary for enrolment in the Graduate Diploma in Medical Ultrasound. </p> <p>This 1-year course is completed part-time, allowing deeper levels of engagement and skills development. Our smaller, more personal study environments offer students the chance to get a more tailored training experience. Dedicated to hands-on learning, you’ll join our industry experts and engage with extensive practical learning in our state-of-the-art training facilities, right here on campus. <br/> </p> Study a Graduate Certificate in Ultrasound Studies and you will: <ul> <li>Be able to apply the physical principles of ultrasound to effective and safe use of medical ultrasound equipment. </li> <li>Apply and demonstrate knowledge of ultrasound scanning techniques, image recognition and acquisition of ultrasound examinations in a simulated environment. </li> <li>Be able to integrate your understanding of anatomy, standard variants, and pathology as depicted in medical ultrasound. </li> <li>Learn to communicate and engage with prospective patients and other health professionals in a professional, safe and ethical manner. </li> <li>Acquire the necessary skills to help you to secure an industry placement, supporting your enrolment in the Graduate Diploma in Medication Ultrasound. <br/> </li> </ul> Career opportunities <p>There is currently a severe shortage of experienced and qualified medical sonographers in the world; and with an ever-increasing aging population, the deficit is expected to get worse. There has never been a better time to consider a career as a medical sonographer. </p> <p>The graduate certificate is a pathway for a career as a medical sonographer, allowing you to work in various areas in Australia and overseas after completion of the Graduate Diploma in Medical Ultrasound. These include but are not limited to: </p> <ul> <li>Public and private hospitals </li> <li>Private radiology practices </li> <li>Applications specialist </li> <li>Research, teaching and education.</li> </ul> Professional accreditation <p>Graduates of this course must successfully complete a Graduate Diploma in Medical Ultrasound to become an Australian Sonographer Accreditation Registry (ASAR) Accredited Medical Sonographer.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Applicants for the Graduate Certificate in Ultrasound Studies must meet one of the following criteria: <br/>A) a completed bachelor degree in medical radiation science; or <br/>B) a completed bachelor degree in any field and successful completion of at least two units of degree level anatomy and physiology</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 <a href="#"></a></td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 <a href="#"></a></td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/HLC501/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '040739C';
UPDATE courses SET
    course_description = 'Design your way with Digital Media <p>Design your dream career with a Bachelor of Digital Design (Digital Media). Delivered in partnership with TAFE Queensland, this specialist course focuses on the essential practical knowledge needed to create complex interactive media. </p> <p>You’ll learn to identify and anticipate emerging technological trends; critically analyse digital and interactive media works and production processes; create advanced digital media artefacts and work effectively in production environments which mirror those found in digital and interactive media workplaces.</p> <p>Complete your degree at our TAFE Queensland Brisbane campus where you''''ll build the foundations of your career and upon graduation, you''''ll be ready to jump into a role in the industry anywhere you choose. </p> Study a Bachelor of Digital Design in Digital Media at UC and you will: <ul> <li>Gain specialist knowledge and skills needed to work across a range of creative areas from animation to virtual reality (VR).</li> <li>Develop an understanding of how digital technology has revolutionised the way we communicate, work, learn and play.</li> <li>Gain up-to-date skills using industry-standard technologies in virtual and augmented reality, digital photography, digital audio, interactive fiction, video and animation. </li> </ul> <p>Upon successful completion you may be able to find work across a range of creative areas.</p> Work Integrated Learning <p>You’ll be encouraged and supported to find relevant work placements, enabling you to experience the reality of working within the industry or a particular company, and the opportunity to build useful networks for a future career. </p> Career opportunities <ul> <li>Digital Media Designer </li> <li>Digital Media Producer </li> <li>Multimedia Artist</li> <li>Animator</li> <li>Digital Photographer </li> <li>Videographer</li> <li>Virtual and Augmented Reality Designer </li> <li>Creative Director </li> </ul> Course Specific information <p>Standard entry to this course is by selection rank, but a portfolio entry is also possible.</p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- diploma pathway <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/> <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2026</td> <td>South Bank, QLD</td> <td>Semester 1 </td> <td>16 February 2026</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Academy Of Interactive Entertainment Ltd (Aie)</b></p> <p> <a href="/credit/33067">Diploma of Screen and Media (CUA51020) - 24 credit points (33067)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/33046">Diploma of Information Technology (33046)</a> </p> <p><b>Tafe Queensland</b></p> <p> <a href="/credit/34388">Diploma of Screen and Media (34388)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB301/2/2026',
    updated_at = NOW()
WHERE cricos_course_code = '102460A';
UPDATE courses SET
    course_description = '<strong>Make an impact with a Bachelor of Communication and Media</strong> <p>Tell stories, share ideas and connect with audiences in powerful and creative ways.</p> <p>At the University of Canberra, our Bachelor of Communication and Media will set you up to succeed as a professional communicator. From day one of your comms studies, you’ll be learning in professional facilities, collaborating with industry, publishing real content and building a portfolio that sets you apart.</p> <p>Get hands-on experience in our campus radio station UCFM (Canberra’s #1 student station!) or see your work published in The Owl, UC’s own journalism and media platform. These experiences ensure your voice is heard and you graduate career-ready.</p> <strong>Specialist majors</strong> <p>Choose from six majors, or mix and match any combination to create a double major:</p> <p><strong>Marketing Communication: </strong>Explore how brands connect with audiences through campaigns, content and digital strategy. Learn to craft persuasive messages, analyse audiences and deliver marketing solutions that get results.</p> <p><strong>Public Relations and Strategic Communication: </strong>Build skills in storytelling, reputation management and advocacy. Learn how to shape public perception, manage crises and engage communities with impact.</p> <p><strong>Journalism: </strong>Develop the skills to research, report and produce compelling stories across digital, print and broadcast media. Gain experience creating accurate, ethical journalism that informs and inspires.</p> <p><strong>Sports Media:</strong> Learn how to cover the stories behind the games, clubs and athletes that shape sport culture. Build specialist skills in commentary, reporting and digital sports coverage.</p> <p><strong>Social Media and Content Creation: </strong>Understand how to plan, produce and share engaging content across platforms. Master analytics, strategy and storytelling to build online communities and influence.</p> <p><strong>Media Production: </strong>Create high-quality video, audio and multimedia content using professional facilities. Develop technical expertise and creative flair for work across film, TV, podcasting and beyond.</p> <strong>Study a Bachelor of Communication and Media and you will:</strong> <ul> <li> <p>Learn by doing, with practical projects, professional briefs and published work from your first semester</p> </li> <li> <p>Explore different majors through our flexible “sample before you specialise” approach before committing to a specialisation</p> </li> <li> <p>Build skills in writing, presenting, digital production, critical thinking and problem solving in spaces like UCFM, TV Studio, editing suites and more</p> </li> <li> <p>Collaborate with academics who are approachable, industry-active and invested in your success</p> </li> <li> <p>Gain up to 200 hours of professional experience, ensuring you graduate confident and career-ready</p> </li> <li> <p>Graduate with a portfolio that demonstrates your creativity, skill and adaptability</p> </li> </ul> <strong>Study your way</strong> <p>This degree is available on campus with flexible study options. You can mix and match majors to create a double major as unique as your ambitions. Whether you’re launching your first career or building on what you’ve started, you’ll benefit from a supportive learning environment, industry-standard facilities and opportunities to connect with professionals.</p> <strong>Work Integrated Learning (WIL)</strong> <p>At UC, Work Integrated Learning (WIL) is built into all our courses. That means you’ll graduate with professional experience already on your CV. From producing content for live clients to working on community campaigns, you’ll have opportunities to get real experience with organisations like the ABC, Crux Media, Seven West Media, the Brumbies, Australian Public Service (APS) and more.</p> <strong>Career opportunities</strong> <ul> <li> <p>Advertising or marketing specialist</p> </li> <li> <p>Brand strategist</p> </li> <li> <p>Editor</p> </li> <li> <p>Journalist, reporter or broadcaster</p> </li> <li> <p>Media producer (video, audio, digital)</p> </li> <li> <p>Publicist, PR manager or media advisor</p> </li> <li> <p>Social media manager or content creator</p> </li> <li> <p>Sports journalist or commentator</p> </li> <li> <p>Strategic communication consultant</p> </li> </ul>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><b>University Of Canberra College</b></p> <p> <a href="/credit/35249">951AA Diploma of Communication (35249)</a> </p> <p> <a href="/credit/35248">951AA Diploma of Communication (35248)</a> </p> <p> <a href="/credit/35228">951AA Diploma of Communication (35228)</a> </p> <p><a href="#">See more</a></p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB105/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '118522E';
UPDATE courses SET
    course_description = '<p> The University of Canberra''''s Master of Business Administration (MBA) will provide you with the chance to develop high-level competencies relevant to a variety of different types of enterprises. You will study the subtle nuances of business in all its forms, with the view to securing future employment in an executive role, in senior management or as an entrepreneur. Our MBA covers all aspects of business administration, including finance, marketing, economics, strategic processes and people management, and culminates in the completion of a research project of your choice. Due to the course''''s strong focus on Work Integrated Learning (WIL) you will graduate with an impressive portfolio of international experience, as well as the solid business mindset required to negotiate your way through an assortment of legal, industrial and cultural settings, and will be confident interacting in an increasingly complex business environment. </p>',
    course_duration_per_week = 78,

    entry_requirements = '<p>Applicants must have a bachelor qualification, or equivalent, in a related field OR Bachelor qualification, or equivalent, in an unrelated field AND three years'''' work experience OR Bachelor qualification, or equivalent, in an unrelated field AND Graduate Certificate in Business or higher.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/723AA/7/2027',
    updated_at = NOW()
WHERE cricos_course_code = '052826E';
UPDATE courses SET
    course_description = 'Establish yourself as a dynamic communication professional <p>Elevate your skills in communication and leadership and create a meaningful impact through UC''''s Master of Communication. Immerse yourself in refining analytical, leadership and engagement skills across diverse communication realms within private, government and community sectors. Tailor your expertise by specialising in either Strategic Communication, Journalism or Marketing and fine-tune your abilities in innovation, social research methods, behaviour change and more. Right from the outset, you’ll engage in contemporary global communication practices and acquire genuine workplace insights in both local and international communication landscapes. Through hands-on experience and projects, you’ll develop a comprehensive understanding of the challenges confronting the communication and media industries. By graduation, you''''ll be ready to take your knowledge back to the workplace and move towards senior roles.</p> Study a Master of Communication and you will: <ul> <li>Demonstrate an in-depth understanding of human communication processes and environments.</li> <li>Become confident in using a range of social research methods relevant to strategic or marketing communication.</li> <li>Demonstrate critical thinking and vision to address mid to long-term strategic communication issues.</li> <li>Become confident in counselling senior management on strategic communication and possess the ability to lead teams within organisations.</li> <li>Link communication research, planning, implementation, and evaluation to organisational strategic plans.</li> <li>Apply your understanding of communication theories towards a major research project.</li> </ul> Work Integrated Learning <p>You’ll have extensive opportunities to connect with industry, including real-world case studies, industry-linked research, and practice projects. Complete 180 hours of a compulsory internship based around a professional industry project of your choosing and develop your professional experience and capabilities in an organisational context. Your internship placement can be in Australia or overseas. Select from advertising agencies, PR firms, government departments, commercial enterprises, and not-for-profit organisations to tailor your internship to your interests.</p> Career opportunities <ul> <li>Public Affairs Officer</li> <li>Brand Manager</li> <li>Social Marketing and Communications Specialist</li> <li>Digital Strategist</li> <li>Research Analyst</li> <li>Political Campaign Manager</li> <li>Marketing Director</li> </ul> Study for less with Commonwealth Support Places (CSP) <p>A course with Commonwealth Supported Places (CSP) means the Australian Government has subsidised a portion of your degree, reducing the total balance you are required to pay (known as the student contribution amount).<br/> The CSP amount is determined by the course you are undertaking and the industry you''''ll be working in after graduation.<br/> For more information on CSP, <a href="https://www.canberra.edu.au/future-students/study-at-uc/fees-and-costs/domestic-fees-and-costs">click here</a>. </p> Course specific information <p>The 12cp Restricted Choice unit list includes units from both specialisation streams as well as carefully selected business and management units, giving you the opportunity to gain more in-depth expertise. If you’re wishing to further your research engagement you can complete the 6cp <a href="https://www.canberra.edu.au/unit/11642/1/2024">Social Research Project PG (11642)</a> unit under the supervision of a News and Media Research Centre professional researcher.<br/> </p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Applicants must have an undergraduate degree (AQF level 7) or equivalent as approved by the University Admissions. <br/> <br/>Applicants who have completed the Graduate Certificate in Academic Foundations (EDC201) are also eligible for entry. <br/> <br/>Students who have completed the Graduate Diploma in Communication (UC) can articulate into the Master''''s course with credit for the 8 units completed. <br/> <br/>Students who have completed the Graduate Certificate in Communication (UC) or the Graduate Certificate in Communication (Engagement) or the Graduate Certificate in Digital Marketing may apply and receive credit for 12 credit points (4 units) of their completed study. <br/> <br/>In making an offer to an applicant, the University will give consideration to a range of factors including English proficiency, academic record and/or employment experience. <br/> <br/>Applicants with a completed Bachelor''''s degree in a related/cognate field may be granted credit for up to 12 credit points of unspecified credit reducing the degree duration to 1.5 Years (EFTSL), additional credit from completed Graduate Certificates in Communication and Graduate Diplomas in Communication may reduce this duration further. <br/> <br/>Defence Members who hold an equivalent rank of O-1 or above as an officer or chaplain, or E06 and above as an SNCO, are eligible for direct entry into this Masters degree as part of the Veteran Tertiary Support Program. <br/> <br/>You can use professional experience and prior learning to enter into a postgraduate qualification at UC through our Professional Pathway Entry program. If you have significant work experience or hold industry-recognised qualifications, this program could be your route to bypass undergraduate study and accelerate your career. Explore Professional Pathway Entry <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry">https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Any Australian Higher Education Provider</b></p> <p> <a href="/credit/35648">Any Completed (AQF 7) Bachelor of Communication or Bachelor of Arts or Equivalent Program (35648)</a> </p> <p><b>Any International Higher Education Provider</b></p> <p> <a href="/credit/35649">Any Completed (AQF 7) Bachelor of Communication or Bachelor of Arts or Equivalent Program (35649)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARM201/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '103874D';
UPDATE courses SET
    course_description = 'Start your sport science career in the right condition <p>If you’re interested in the science of human movement, but not sure what specialty to focus on, then the 6-month, full time Graduate Certificate in Human Movement Science course is the perfect way to start your career path on the right foot.<br/> This course will boost your knowledge of functional anatomy, biomechanics and exercise physiology while setting the groundwork to allow your study to articulate into a variety of other sports related pathways.</p> <p>This course allows you to bridge the knowledge gap for graduate entry into a number of Masters programs. This includes UC''''s Master of Speech Pathology and satisfies the Australian Physiotherapy Association''''s requirements for entry into the Master of Physiotherapy.</p> Study a Graduate Certificate in Human Movement Science at UC and you will: <ul> <li>broaden the skills and knowledge you developed during an undergraduate science degree</li> <li>learn functional anatomy, biomechanics and exercise physiology</li> <li>build on your biological or medical science bachelor’s degree to be able to apply for our Master of Physiotherapy and Master of Speech Pathology degrees.</li> </ul> Career opportunities <p>Opportunities exist for Graduate Certificate in Human Movement Science graduates in the sporting organisation sector, including:</p> <ul> <li>conducting sports science research</li> <li>gateway to further study in strength and conditioning and physiotherapy</li> <li>delivering sport science services for sporting teams and institutes</li> <li>conducting sports events for organisations.</li> </ul> Professional accreditation <p>None.</p>',
    course_duration_per_week = 26,

    entry_requirements = '<p>A completed bachelor degree in a science discipline*. <br/> <br/>* Science disciplines include biology, chemistry, medical science or biomedical science. <br/> <br/>Admission to this course is competitive. Applications will be assessed on the basis of academic merit and the number of available places.</p> Assumed knowledge <p>Applicants are required to meet the normal University''''s requirements for admission to a graduate certificate course. Additionally, having prior tertiary education in anatomy and physiology would be beneficial.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/868AA/4/2027',
    updated_at = NOW()
WHERE cricos_course_code = '056140C';
UPDATE courses SET
    course_description = 'Take the ultimate fitness (and wellness) test! <p>Combine the skills and knowledge of a coach or sports scientist with that of a nutritionist by studying the national capital’s fittest double degree!</p> <p>The Bachelor of Health Science (Human Movement)/Bachelor of Human Nutrition course combines the scientific health and human movement studies behind elite sports, including human physiology and anatomy, with pathobiology, food and consumer science and studies in food nutrition in sport.</p> <p>You’ll develop a unique blend of skills from our expert teachers, including the delivery of clinically focused personalised support and the methods and applications used in the science of human movement – all while gaining a clear and critical understanding of the psychological, social and cultural aspects of food’s relationship to health and wellbeing in sport. </p> <p>If you’re interested in cutting-edge pathways to postgraduate study that will give you an edge and hands-on work opportunities that maximise athletic performance at the elite level, this is the course for you. Apply for the ultimate fitness test today. </p> Combine a Bachelor of Health Science (Human Movement) and Bachelor of Nutrition at UC and you will: <ul> <li>be ready to maximise athletic performance at the elite level</li> <li>gain strong knowledge of the theory and practice of coaching</li> <li>develop a sound scientific foundation in sport and build your knowledge of the core topics of the discipline of human movement and nutrition</li> <li>understand factors that influence eating behaviour and food responses</li> <li>master the research methods used by sports scientists and learn how to apply these to the design and conduct of scientific studies as well as write clinical reports and interpret results</li> <li>enhance your ability to apply your knowledge in a critical way to problems related to human nutrition and physical performance</li> <li>increase your understanding and application of the values and professional ethics in sports development and nutrition research.</li> </ul> Career opportunities <p>A UC Health Science (Human Movement)/Bachelor of Human Nutrition double degree opens doors in a range of sectors in the innovative world of sports and nutrition science as well as the education and health arenas, including:</p> <ul> <li>exercise physiology</li> <li>sports administration</li> <li>sports nutrition</li> <li>dietetics</li> <li>exercise scientist</li> <li>biomechanics</li> <li>policy development</li> <li>public health</li> <li>program co-ordination and welfare</li> <li>coaching</li> <li>biological and medical sciences</li> <li>rehabilitation services</li> <li>training and fitness instruction</li> <li>aged care</li> <li>research</li> <li>physical education</li> <li>health administration, promotion and research</li> <li>food regulation.</li> </ul> Professional accreditation <p>Refer to individual courses.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>ACT: Biology, Chemistry, Mathematical Methods and Physics majors. NSW: Biology, Chemistry, Mathematics and Physics.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/HLHL01/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '099024G';
UPDATE courses SET
    course_description = 'Become a global leader and business specialist <p>UC’s Master of Business Administration (Plus) will allow you to develop high-level skills and competencies relevant to managing an organisation. Additionally, you’ll have the opportunity to specialise in human resource management, marketing or international business by taking four additional units, accelerating your career progression to become a capable and adaptable business leader.</p> <p>You will study the subtle nuances of business in all its forms, with the mindset of future employment opportunities in an executive role, senior management or as an entrepreneur. UC’s MBA (Plus) covers all aspects of business administration, including finance, marketing, economics, strategic processes and people management and culminates in a research project of your choice.</p> <p>What sets our MBA (Plus) degree apart is the opportunity to dive deeper into a specific field. Select one of three areas of specialisation that allow you to explore human resource management, marketing or international business to align with your overall business management aspirations.</p> <p>Thanks to UC’s strong focus on Work Integrated Learning (WIL), you will graduate with an impressive portfolio of international experience. You’ll gain a solid business mindset required to negotiate your way through an assortment of legal, industrial and cultural settings. Study UC’s Master of Business Administration (Plus) and have the confidence to navigate an increasingly dynamic and ever-changing business landscape.</p> Study a Master of Business Administration (Plus) at UC and you will: <ul> <li>formulate a marketing strategy, with particular emphasis on the development of product, distribution, promotion, pricing strategies and tactics.</li> <li>understand and apply the basic techniques of corporate finance.</li> <li>demonstrate an understanding of the broad body of knowledge inherent in the process of strategic management.</li> <li>compare and contrast different forms of entrepreneurial theory and thinking in its role for idea and business development in the global economy.</li> <li>demonstrate a critical understanding of fundamental economic theories and learn how best to apply them in practical business situations.</li> <li>become a versatile business expert with specialised knowledge in an area of your choice.</li> </ul> Work Integrated Learning <p>Due to the global focus of the MBA (Plus) and our connection with partners in Singapore, Bhutan and Ningbo and Shanghai in China, you can apply for an international internship as part of your MBA (Plus) experience. Hone your leadership skills with fellow UC MBA students from around the globe on a variety of Australian and international business assignments. Projects range from small to medium-sized enterprises, councils, government departments and community groups, across a range of industries, such as farming, tourism, transport and more.</p> <p>A key component of the Master of Business Administration and MBA (Plus) is to undertake a specialised real-world research project of your choosing. This will enhance your employability and ensure you are armed with the right mix of skills and practical knowledge to take a confident leap into the next phase of your business career.</p> Career opportunities <ul> <li>Company Director</li> <li>President</li> <li>Vice President</li> <li>Chief Executive Officer</li> <li>Chief Financial Officer</li> <li>Board Member</li> <li>Marketing Director</li> <li>Entrepreneur</li> <li>Management Consultant</li> <li>HR Director</li> <li>Venture Capitalist</li> <li>Head of Finance</li> <li>IT Director</li> <li>Angel Investor</li> <li>Health Services Director.</li> </ul> <p>The Master of Business Administration (Plus) includes four additional units and face-to-face learning that can further enhance your area of specialisation. The MBA (Plus) also meets the academic entry requirements for international students.</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Applicants must have an undergraduate degree or equivalent as approved by the University.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/MGM102/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '098430A';
UPDATE courses SET
    course_description = 'Explore new horizons with a double degree in arts and psychology <p>Combine the creativity of a versatile and professionally-oriented arts degree with the psychological insights of a psychology degree. Together, your knowledge will unlock career possibilities across art, science, psychology, digital media, journalism and beyond. </p> <p>Bachelor of Arts/Bachelor of Science in Psychology double degree will give you the tools and understanding to become an innovative and engaged creative thinker, with a clear and critical understanding of scientific psychology theories and research methods. Across your studies, you''''ll establish a creative perspective with a solid foundational pathway for those considering becoming a professional psychologist.</p> Combine a Bachelor of Arts with a Bachelor of Science in Psychology at UC and you will: <ul> <li>Explore creative ideas and ideologies designed to stimulate discussion and influence change</li> <li>Increase your knowledge of the scientific basis and core topics in the discipline of psychology, including in psychopathology, cognition and perception</li> <li>Increase your knowledge of the research methods used by psychologists and learn how to apply these methods to the design and conduct of studies and analyse and interpret results and write reports</li> <li>Enhance your ability to react in a critical way to problems related to behaviour and mental processes, and learn to distinguish scientific evidence</li> <li>Increase your understanding and application of values, research and professional ethics in psychological research and other professional contexts</li> </ul> Career opportunities <p> UC''''s Bachelor of Arts/Bachelor of Science in Psychology degree opens many doors in a range of public and private sectors, including: </p> <ul> <li>Clinical psychology</li> <li>Policy and research</li> <li>Youth work</li> <li>Consumer research</li> <li>Advertising and marketing</li> <li>Human resources</li> <li>Industrial relations</li> <li>Program co-ordination and welfare</li> </ul> Professional accreditation <p>The Bachelor of Science in Psychology is accredited by the Australian Psychology Accreditation Council (<a href="https://apac.au/">https://apac.au/</a> )</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>For Work Integrated Learning (WIL) in Psychology, students may require a Working with Vulnerable People card.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 <a href="#"></a></td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 <a href="#"></a></td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/ARSC01/4/2027',
    updated_at = NOW()
WHERE cricos_course_code = '098995G';
UPDATE courses SET
    course_description = 'Turn your passion for human movement into a career <p> The Bachelor of Health Science (Human Movement) focuses on human performance, as well as the roles and benefits of exercise and physical activity. </p> <p> You''''ll gain a foundation in sport sciences as it relates to human movement and sport performance, including fundamental concepts in exercise physiology, biomechanics, motor control and exercise programming and prescription. You''''ll develop skills in physiological testing procedures, biomechanical analyses to measure a range of parameters relating to physical activity, exercise and sport performance. You’ll also have opportunities to gain experience in a number of health workplace settings embedded into your degree. <br/> </p> <p> You’ll graduate with a strong academic base in both sport and health science disciplines related to human movement, physical activity and performance, and be well equipped to undertake further postgraduate study in research, high-performance sport or other allied health degrees. Further study opportunities include Bachelor of Health Science (Honours), Master of Strength and Conditioning, Master of Occupational Therapy and Master of Physiotherapy. </p> Study a Bachelor of Health Science (Human Movement) at UC and you will: <ul> <li>Work individually, collaboratively and ethically while building professional networks in the health sector.</li> <li>Translate and communicate discipline-specific knowledge to a variety of health-related audiences such as professionals, government and non-government representatives and clients.</li> <li>Develop and apply critical analysis skills to a range of contemporary health-related issues.</li> <li>Develop technical, technological and communication skills to provide health or sport solutions for increasingly complex problems.</li> <li>Design, apply and evaluate appropriate interventions for improved health or performance outcomes.</li> <li>Apply theoretical knowledge to practical situations in laboratory-simulated learning environments and community and industry settings, independently and as part of a team.</li> <li>Analyse and explain the impact of physical activity on human development and performance.</li> </ul> Work Integrated Learning <p> Work Integrated Learning (WIL) is at the very centre of all UC degrees. You’ll complete units designed to help you develop the professional skills essential for employment in the health industry. You will work and study in real-world situations, learning from industry-active professionals and world-class scholars and graduate highly employable with the skills and knowledge for success. <br/> </p> <p> As part of your degree, you will undertake a 120-hour WIL experience during the final year of your course. </p> Career opportunities <ul> <li>Sport and Recreation Officer</li> <li>Corporate health</li> <li>Strength and conditioning</li> <li>Public policy</li> <li>Sports Coach</li> <li>Human movement research and development</li> </ul> Course-specific information <p> You will be required to hold a valid Working with Vulnerable People registration. </p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><b>University Of Canberra College</b></p> <p> <a href="/credit/22010">Diploma of Health (22010)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/HLB101/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '098277E';
