UPDATE courses SET
    course_description = '<strong>Grow your career in nutrition and dietetics from the inside out</strong> <p>If you’re serious about nutrition and influencing the dietary needs of an ever-expanding and ageing population, then UC’s Master of Nutrition and Dietetics will give you the necessary skills and qualifications to have your ideas influence change at the local and national level.</p> <p>As part of this course, you’ll use your existing knowledge and experience to plan and execute a research project of your choice. You will also participate in 20 weeks of full-time workplace education to help bring this project to life, all with full support and encouragement from academic and industry experts and mentors.</p> <p>Depending on your research topic, this placement will take place in settings which offer a unique opportunity to gain frontline experience and network with industry professionals, including hospitals, community centres or food service departments.</p> <p>The Master of Nutrition and Dietetics is the only course in Australia that offers all graduating students an additional 4-week internship, where you are actively encouraged to broaden your networks and explore employment opportunities at the same time.</p> <strong>Study a Master of Nutrition and Dietetics at UC and you will:</strong> <ul> <li> <p>Develop additional knowledge, skills and attitude to examine health within the framework of nutrition.</p> </li> <li> <p>Understand the application of nutrition in a socio-cultural, pathophysiological and biochemical health context.</p> </li> <li> <p>Cultivate critical thinking skills, problem-solving skills and apply evidence-based approaches to address a nutrition-related health issue.</p> </li> <li> <p>Demonstrate expert communication skills to transfer complex nutrition knowledge to a variety of audiences.</p> </li> <li> <p>Develop autonomy and self-direction in progressing your learning and professional development.</p> </li> <li> <p>Gain the necessary scientific background and specific knowledge and skills to address concepts and opinions relating to human nutrition.</p> </li> <li> <p>Identify the links between nutrition, health and disease at different life stages.</p> </li> <li> <p>Address ways to improve the delivery of nutritional information.</p> </li> </ul> <strong>Work Integrated Learning</strong> <p>This course includes up to 24 weeks of full-time workplace education in a range of settings, including the public health sector, hospitals, food services or in the community.</p> <p>All work completed during this placement will count towards your end-of-course assessment and is part of the UC Faculty of Health’s commitment to helping students gain valuable hands-on experience and build life-long industry contacts and relationships while they are studying at UC.</p> <strong>Career opportunities</strong> <p>A Master of Nutrition and Dietetics graduate is recognised as possessing the necessary skills, experience and qualifications to become an Accredited Practising Dietitian. This accreditation is also accepted globally and opens doors to a range of jobs in a variety of industries, including:</p> <ul> <li> <p>hospitals</p> </li> <li> <p>community health centres</p> </li> <li> <p>private practice</p> </li> <li> <p>government departments</p> </li> <li> <p>the food industry</p> </li> <li> <p>media</p> </li> <li> <p>education</p> </li> <li> <p>research.</p> </li> </ul> <strong>Course-specific information</strong> <p>Before undertaking any clinical placement, students will be required to:</p> <ul> <li> <p>Undertake a National Police Check.</p> </li> <li> <p>Obtain a Working with Vulnerable People registration.</p> </li> <li> <p>Provide immunisation history.</p> </li> <li> <p>Hold both First Aid and CPR qualifications.</p> </li> </ul> <strong>Professional accreditation</strong> <p>This course has been accredited by Dietitians Australia.</p> Professional accreditation <p>This course has been accredited by Dietitians Australia (DA).</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>Applicants must meet all of the following criteria: <br/>A) a completed bachelor degree in human nutrition <br/>B) two degree level units in chemistry <br/>C) four degree level units in human biology and human physiology <br/>D) two second year degree level units in biochemistry <br/>E) four degree level units in food and nutrition science</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/772AA/7/2027',
    updated_at = NOW()
WHERE cricos_course_code = '049506C';
-- ⏭️ Skipped (no CRICOS): Juris Doctor | https://www.canberra.edu.au/course/SCM002/1/2027

UPDATE courses SET
    course_description = 'Use your creativity to educate primary school children <p>This innovative four-year degree will enable you to become a primary school teacher with a specialisation in the creative arts. On top of gaining practical experience of the educational theories used in today’s classrooms, you’ll develop a solid understanding of national literacy and numeracy requirements for children from Kindergarten to Year 6, while specifically focusing on subjects including visual arts, drama, music and dance.</p> <p>During your second, third and fourth year of study, you’ll take a range of Pedagogical Content Knowledge (PCK) units which are taught on-site in primary schools, offering you the opportunity to connect with students across all primary year levels in subjects including English, science, maths, health and PE, technologies, humanities and social sciences, as well as via a specific arts education internship. You’ll graduate ready to inspire children aged five to 12, using creativity, imagination and ingenuity.</p> Study a Bachelor of Primary Education (Creative Arts) at UC and you will: <ul> <li>Gain appropriate scientific, literacy and numeracy knowledge.</li> <li>Learn the theories and principles that are the foundation for educational practice in primary settings.</li> <li>Demonstrate an understanding of student needs and differences, and the relevance of these to learning in inclusive, indigenous, English as an Additional Language or Dialect (EALD) and mainstream settings.</li> <li>Plan and develop appropriate teaching activities for students from a diverse range of backgrounds.</li> <li>Develop and implement effective assessment strategies and carry out evaluation of teaching programs, resources and your own teaching.</li> <li>Apply the required content knowledge for all primary school curriculum areas to teaching, assessment and reporting methods, alternate/enhanced literacy and numeracy strategies, and the effective use of Information and Communication Technologies (ICT) in teaching and learning.</li> <li>Reflect on your practice and experiences, and engage in a process of continual improvement.</li> </ul> Work Integrated Learning <p>A teaching degree, by its very nature, is the embodiment of Work Integrated Learning (WIL), with its focus on compulsory professional teaching practice. During this course, you’ll undertake a minimum of 80 days of practical placement across a range of different primary school levels and settings, including creative arts-specific positions, culminating in a 30-day Arts Education Internship in your final year.</p> <p>In addition, the course content is developed by primary education professionals and kept relevant and up-to-date through consistent monitoring of and engagement with the industry. You’ll undertake authentic assessment tasks that are highly relevant to the day-to-day practice of teaching and will take part in regular professional development activities, field trips to educational sites, lectures hosted by guest speakers from a range of education and teaching backgrounds and more.</p> Career opportunities <ul> <li>Primary School Teacher</li> <li>Drama Teacher</li> <li>Visual Arts Teacher</li> <li>Music Teacher</li> <li>Dance Teacher</li> <li>Principal</li> <li>Deputy Principal</li> <li>Executive Teacher</li> <li>Special Needs Teacher</li> <li>Gifted and Talented Teacher</li> <li>Relief Teacher</li> <li>Private Tutor</li> <li>Schools Policy Adviser</li> <li>Children’s Services Manager</li> <li>OSHC Coordinator (Out of School Hours Care)</li> <li>Schools Engagement Coordinator.</li> </ul> Course-specific information <p>This course is registered by the ACT Teacher Quality Institute (TQI) and recognised as a teaching qualification throughout Australia.</p> <p>Upon graduation, students must register with the appropriate state teaching body in order to teach.</p> <p>Students must obtain a Working with Vulnerable People check before their first placement.</p> Professional accreditation <p>This course is registered by the ACT Teacher Quality Institute (TQI) and recognised as a teaching qualification throughout Australia.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>All applicants will be required to complete a written statement in response to questions designed to assess their suitability for the teaching profession. Applicants'''' responses to these questions must be deemed satisfactory for them to be admitted to this course. You can find the questions in the ''''resources'''' section of the online application portal when you are applying. You can upload your responses in PDF format as part of your application. <a href="https://www.canberra.edu.au/about-uc/faculties/education/docs/UG-Teacher-Education-questionnaire.pdf">https://www.canberra.edu.au/about-uc/faculties/education/docs/UG-Teacher-Education-questionnaire.pdf</a> <br/> <br/>Students must obtain a Working with Vulnerable People Check.</p> Assumed knowledge <p>ACT: English &amp; Maths (T with C minimum pass) NSW: Higher School Certificate English &amp; Maths minimum</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/323JA/5/2027',
    updated_at = NOW()
WHERE cricos_course_code = '088692F';
UPDATE courses SET
    course_description = 'Ignite your creativity with a double degree in design, communication and media <p>Study a double degree in design, comms and media with UC’s Bachelor of Design/Bachelor of Communications and Media. As a student of design, your job is to create an experience that is functional, beautiful, intuitive and accessible. As a communications and media student, your challenge is to examine creative ideologies, a range of platforms and target audiences and develop solutions to influence change. Together these two disciplines will give you the knowledge and skills to forge a creative career full of inspiration, problem-solving and great stories.</p> <p>You''''ll explore the complexity of design and discover how creativity, form and function can inspire and influence. Combine this with the hands-on knowledge and experience required of journalists, marketing managers and other media and communications professionals around the world, blending disciplines to forge an exciting creative career with tangible results. </p> <p>Taught in small, more personalised classes, the course offers an individually-tailored learning environment that ensures each student receives the highest level of support and encouragement throughout their UC journey.</p> <p>Specialise in one of four professional communications areas: Journalism, Marketing Communication, Corporate and Public Communication or Sports Media. </p> <p>Design offers five specialisations: a generalist Design major that brings together industrial, interaction and visual communication design; Interaction Design (digital experiences and UX/UI), Industrial Design (innovative physical products), Visual Communication Design (brands, campaigns, and visual language), or Game Development (game art, design, and programming). </p> Combine a Bachelor of Design and a Bachelor of Communications and Media at UC and you will: <ul> <li>Identify the different stages of the ‘design for manufacture’ process</li> <li>Build the knowledge and skills necessary to launch your own interaction design business or seek employment within global markets across all industries.</li> <li>Learn the appropriate methods, materials and processes for designing and prototyping products</li> <li>Employ innovative use of different visual and emerging media types across print, screen and packaging</li> <li>Develop effective design solutions for specific audiences and learn to apply advanced 2D and 3D digital design technologies</li> <li>Apply professional judgement and knowledge in adapting marketing communication theories, principles and methodologies across diverse social, cultural and organisational contexts</li> <li>Explore narratives that inform, persuade and generate change</li> </ul> Career opportunities <p>The career choices are virtually endless with UC’s Bachelor of Design/Bachelor of Communications and Media. Graduates will be able to explore working in a wide range of creative and/or communications roles, such as:</p> <ul> <li>Industrial Designer</li> <li>Urban Planner</li> <li>Set Designer</li> <li>Graphic Designer</li> <li>Design Consultant</li> <li>Digital Manufacturing Designer</li> <li>Creative Copywriter</li> <li>Editor</li> <li>Advertising Account Manager</li> <li>Content Developer</li> <li>Digital Media Specialist</li> <li>Social Media Manager</li> <li>Journalist</li> <li>Campaign Manager</li> <li>Media or Marketing Analyst</li> <li>Producer</li> <li>Publisher </li> </ul> Professional accreditation <p>Refer to individual courses.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/ARAR02/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '084222B';
UPDATE courses SET
    course_description = '<strong>Boost your skills and knowledge in public policy, management and administration to pursue a career where you can make a difference.</strong> <p>Fascinated about the business of government? Tailored for ACT and Federal government staff, this course is a boost for your career in government. You’ll explore the latest trends and developments in public administration, public sector management, policy research and evaluation, financial budgeting and management.</p> <p>Need a flexible method of study that suits the challenges of your job? This course is delivered using a combination of on-line and traditional teaching methods comprising lectures, tutorials and workshops. Giving yourself a career boost was never easier!</p> <strong>Your future career</strong> <p>This course will give you additional knowledge and skills in public administration and evaluation to take your career to the next level. This course could also be a pathway to study at a Master level. You could find work in the government and public sector, the not-for-profit sector and in business. Careers could include:</p> <ul> <li>Policy Officer</li> <li>Policy Evaluation Officer</li> <li>Strategic and Implementation Officer</li> <li>Public Sector Manager</li> </ul> <strong>Course specific information</strong> <p>You must have a degree or equivalent as approved by the Academic Quality and Standards Committee <strong>or hold two or more years of relevant work experience.</strong></p> <p>You must be currently employed by an Australian Commonwealth, State or Territory Government Department.</p> <p>Please note it is not open for general admission. If you are interested in a public policy degree, please see the <a href="https://www.canberra.edu.au/course/SCC101/1/2022">Graduate Certificate in Public Policy</a> (SCC101).</p> Professional accreditation <p>None.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Applicants must have a degree or equivalent as approved by the Academic Quality and Standards Committee and be currently employed in the graduate programme of an Australian Commonwealth, State, or Territory Government Department, OR hold two or more years of relevant work experience. <br/> <br/>Note: this course is only offered on a contract basis with Government agencies and is not open to general admission entry.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 1 <a href="#"></a></td> <td>25 January 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 2 <a href="#"></a></td> <td>30 March 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 3 <a href="#"></a></td> <td>01 June 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 4 <a href="#"></a></td> <td>02 August 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 5 <a href="#"></a></td> <td>27 September 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Period 6 <a href="#"></a></td> <td>29 November 2027</td> <td> Open for domestic admissions </td> <td></td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/739AD/3/2027',
    updated_at = NOW()
WHERE cricos_course_code = '040739C';
UPDATE courses SET
    course_description = 'Mind your business and manage your future <p>Whether you’re currently a manager, or wish to become one, the Bachelor of Business (Management) will help you gain a broad theoretical and technical knowledge in a range of core areas of business, plus the skills necessary to be effective in the changing context of work, organisations and business. You’ll study how management underpins business operations in different settings and will develop innovative answers to problems facing businesses into the future.</p> <p>The course will focus your oral and written communication skills through industry-based assignments that reflect real-world business scenarios. Throughout this applied degree, you’ll analyse, review and investigate business problems to provide inventive solutions for private, public and not-for-profit enterprises. You’ll graduate as an agile, multiskilled business professional with the transferable employability skills and creative abilities to succeed as a manager in whichever sector you choose to explore.</p> Study a Bachelor of Business (Management) at UC and you will: <ul> <li>integrate theory and practice in management and articulate the impacts of recent developments within the field.</li> <li>critically evaluate a range of core business skills to find solutions to future work challenges in legal, economic and global business environments.</li> <li>analyse and apply a range of contemporary approaches to business innovation and organisational change.</li> <li>develop experience in professional management of work and organisations, demonstrating creativity and initiative in new situations.</li> <li>apply a range of ethical, socially responsible and sustainable solutions in a changing business environment.</li> <li>reflect upon levels of personal autonomy and accountability associated with the decision-making process.</li> <li>locate and evaluate a range of research frameworks and skills within management.</li> </ul> Study your way <p>Enjoy the freedom of choice: select the online study mode for self-paced learning and optimal study-work-life balance, or on-campus study mode for face-to-face classes.</p> Work Integrated Learning <h5>On campus </h5> <p>The Bachelor of Business (Management) integrates theory with real-world practice through UC''''s Work Integrated Learning (WIL) opportunities, designed to prepare students for their future careers. UC provides diverse WIL options, including industry case studies, guest speakers, internships, work placements, industry projects, competitions, exhibitions, study tours, virtual experiences and more. </p> <p>You’ll undertake hands-on management practice using both hypothetical and real-world scenarios, including the development of critical management plans and industry projects. Previous management students have undertaken internships across a range of sectors, with organisations including the Australian College of Nursing, Brumbies Rugby, Cooma Chamber of Commerce, UniLodge (UC), Careers UC, RDA Southern Inland, Goulburn Regional Conservatorium and Southern Tablelands Arts.</p> <h5>Online</h5> <p>Students who choose to study online can access virtual WIL opportunities. This content includes on-demand guest lectures, industry case studies and industry projects. </p> <p>Internships and the International Business Study Tour options require either in-person placement hours in a business or on an overseas study tour and are not offered wholly online.</p> <p>Students studying both face-to-face and online will have access to support services including Careers UC, who are available to assist with employment pathways and personal development.</p> Career opportunities <ul> <li>Chief executive officer</li> <li>Chief financial officer</li> <li>Chief operating officer</li> <li>Managing director</li> <li>Director</li> <li>General manager</li> <li>Marketing manager</li> <li>Administrative services manager</li> <li>Project manager</li> <li>Commercial director</li> <li>Head of operations</li> <li>Business manager</li> <li>Assistant director</li> <li>Deputy manager</li> <li>Human resources adviser</li> </ul> Course-specific information <p>High-achieving students can enrol in the Bachelor of Business, Government and Policy (Honours).</p> Are you ready to study Business online at the Australia’s #1 Business School*? <p>Download your free course brochure to learn more about UC''''s online Bachelor of Business (Management).</p> <p>*#1 Business School in Australia for Career Impact (AFR BOSS, 2023).</p> <p><a href="https://www.canberra.edu.au/future-students/study-at-uc/about-our-courses/bachelor-of-business">Download your free course brochure</a></p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2026</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>16 February 2026</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2026</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>10 August 2026</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Hainan College Of Economics And Business</b></p> <p> <a href="/credit/33306">Sino-Australia Programme, Accounting Stream (33306)</a> </p> <p><b>Henan University Of Engineering</b></p> <p> <a href="/credit/33266">5 Majors - Financial Management, International Economics and Trade, Accounting (CPA China Certified) (33266)</a> </p> <p><b>Namseoul University</b></p> <p> <a href="/credit/32310">Study in the Global Distribution &amp; Marketing or International Trade Programs (32310)</a> </p> <p> <a href="/credit/32306">Study in the Business Administration Program (32306)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><a href="#">See more</a></p>',
    apply_form = 'https://www.canberra.edu.au/course/MGB105/2/2026',
    updated_at = NOW()
WHERE cricos_course_code = '095936K';
UPDATE courses SET
    course_description = 'Take your career to new heights <p>If you’re keen to become an accomplished professional in the building industry, the Bachelor of Building and Construction Management (Honours) will equip you with the necessary skills to become a confident leader. Learn management and supervision techniques while developing detailed knowledge of building processes and materials. This expertise, together with real-world negotiation, presentation and communication skills, will prepare you for a career in Building and Construction Management within a variety of practice settings.</p> <p>The course includes studies in management and construction, material and structures laboratories, information technology in building (including BIM), quantity surveying, and work integrated learning practice over four years. The degree has an embedded honours component which prepares students to develop advanced knowledge and skills for professional work, critical thinking and further learning corresponding to AQF Level 8 qualifications.</p> Study our Bachelor of Building and Construction Management at UC and you will: <ul> <li>Acquire advanced knowledge of building and construction management principles and concepts and apply them with initiative and judgment.</li> <li>Possess a comprehensive understanding of practising projects, engineering management, building economics and legal frameworks in the construction industry.</li> <li>Apply appropriate and state-of-the-art construction technologies and processes to solve complex industry-related problems.</li> <li>Take responsibility and demonstrate accountability for professional learning, practice and development</li> <li>Address real-world issues with ethical, social, and environmental responsibility, considering global and local contexts and Indigenous rights.</li> <li>Apply creative, innovative, and critical thinking to solve problems and generate solutions in construction.</li> <li>Communicate professionally with key stakeholders in the construction industry, working independently or as part of a team to deliver projects successfully.</li> <li>Utilise cognitive and technical skills to identify and complete research works addressing complex issues related to building and construction practice for enabling business development.</li> <li>Effectively communicate solutions and research outcomes to diverse audiences.</li> </ul> Career opportunities <ul> <li>Builder</li> <li>Developer</li> <li>Construction Contractor</li> <li>Construction Manager</li> <li>Site Manager</li> <li>Building Surveyor</li> <li>Project Estimator</li> <li>Facility Manager</li> <li>BIM Coordinator/Manager</li> </ul> Work Integrated Learning <p>Individual professional accreditation with the Australian Institute of Building (AIB) requires the completion of 60 days (or equivalent) of work experience. Students complete 48 days as part of the course and the remaining 12 days need to be completed through a combination of on-campus activities (including guest lectures etc) and/or the student''''s own work experiences outside university study.</p> Professional accreditation <p>The Bachelor of Building and Construction Management (Honours) has provisional accreditation with the Australian Institute of Building (AIB) and the Australian Institute of Quantity Surveyors (AIQS).</p> Professional accreditation <p>The Bachelor of Building and Construction Management (Honours) has provisional accreditation with the Australian Institute of Building (AIB) and the Australian Institute of Quantity Surveyors (AIQS). <br/> <br/>Individual professional accreditation with the Australian Institute of Building (AIB) requires the completion of 60 days (or equivalent) of work experience. Students complete 48 days as part of the course and the remaining 12 days need to be completed through a combination of on-campus activities (including guest lectures etc) and/or the student''''s own work experiences outside university study.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>All students are required to complete their White Card training prior to the commencement of their first work placement. <br/></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/27753">Diploma of Building and Construction (Building) (27753)</a> </p> <p> <a href="/credit/27733">Diploma of Building and Construction (Management) (27733)</a> </p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35189">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (12CP) (35189)</a> </p> <p><b>Henan University Of Engineering</b></p> <p> <a href="/credit/30039">Advanced Diploma of Civil Engineering (30039)</a> </p> <p><b>Henan University Of Engineering</b></p> <p> <a href="/credit/31384">Bachelor of Project Costs (31384)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35208">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (12CP) (35208)</a> </p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p><b>University Of Canberra College</b></p> <p> <a href="/credit/34069">Diploma of Design (Design and Communication Stream) (34069)</a> </p> <p><b>Xiamen University Of Technology</b></p> <p> <a href="/credit/30838">Bachelor of Civil Engineering (30838)</a> </p> <p><b>Zhejiang Tongji Vocational College Of Science And Technology</b></p> <p> <a href="/credit/30839">Advanced Diploma of Engineering Cost (Hydraulic Engineering Cost) (30839)</a> </p> <p><a href="#">See more</a></p>',
    apply_form = 'https://www.canberra.edu.au/course/ABB101/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '103843M';
UPDATE courses SET
    course_description = 'Raise the bar with a career in law <p>If you’ve aspired to a career in legal practice, then UC''''s Bachelor of Laws will help get you there in no time. Our highly practical approach is a marked strength, and continues to set our law degree apart from the rest.</p> <p>With small class sizes, a purpose-built eMoot Court and highly qualified and experienced staff, you’ll be encouraged to develop your advocacy abilities and legal skills while understanding their connection to legal history and law in context.</p> <p>You can tailor your individual study program by selecting a variety of electives across many areas of law, and even choose to accelerate your studies with winter term subjects. The course will ground your education in the latest legal innovations, develop your communication and interpersonal skills and allow you to become an agile, ethical and effective legal professional.</p> Graduate Entry <p>Experience counts at UC.</p> <p>If you’ve already completed an Australian Bachelor’s Degree or equivalent, you’ll be able to complete our Bachelor of Laws in 3 years instead of 4. Credit is simply applied towards your open electives, which means you can complete your studies sooner.</p> Study a Bachelor of Laws at UC and you will: <ul> <li>Undertake in-depth study of key areas of law that give you the required academic knowledge for admission to Australian legal practice</li> <li>Choose from an array of specialist electives that include environmental law, government law, gender, commercial law, technology, legal innovation and more</li> <li>Participate in a program of study with a proven track record of excellence in graduate employment outcomes and work-integrated learning</li> <li>Have the option of completing Honours in your final year of study. This allows you to graduate with a deeper understanding of the various technical and theoretical aspects of the law and can help prepare you for a variety of roles within and outside the justice sector</li> </ul> Work Integrated Learning <p>The course encourages you to apply your talents in the real world, with opportunities to complete a law internship and international study through links with law firms, governments, non-governmental agencies and overseas universities.</p> <p>You will have the opportunity to choose one law elective which includes a practical Work Integrated Learning (WIL) based component. Past student internship examples have included:</p> <ul> <li>Small, medium and large law firms</li> <li>Community legal centres</li> <li>Government departments (both ACT and federal)</li> <li>Courts</li> <li>Community organisations such as Victim Support ACT</li> <li>Overseas placements in the US at The Carter Center and the Office of the State Public Defender (California).</li> </ul> <p>You’ll also have access to WIL opportunities at the University’s Legal Advice Clinic for Small Business, where students assist legal professionals in providing free legal and financial services to small businesses, local residents and students.</p> Career opportunities <ul> <li>Solicitor*</li> <li>Barrister*</li> <li>Associate*</li> <li>Judge*</li> <li>Judge’s associate</li> <li>Magistrate*</li> <li>Registrar</li> <li>Policy adviser</li> <li>Legal researcher</li> <li>Community lawyer*</li> <li>Justice policy officer</li> <li>Parliamentary counsel</li> <li>Legislative drafter</li> <li>Law reform officer</li> <li>Finance sector</li> <li>Governance</li> <li>Management</li> <li>Licensing</li> <li>Building and Construction</li> <li>Business</li> </ul> <p>*Subject to satisfactory completion of an undergraduate law degree and successful completion of a Graduate Diploma in Legal Practice, which qualifies you for admission to practice as a lawyer.</p> Course-specific information <p>The Bachelor of Laws is structured around the professional requirements for admission to legal practice.</p> <p>UC’s Bachelor of Laws has professional accreditation with the Supreme Courts of both the ACT and New South Wales and through mutual recognition the degree may serve as the basis for admission in all Australian jurisdictions. You may choose to undertake the Bachelor of Laws as a combined degree to widen your future career options.</p> <p>The Bachelor of Laws allows high-achieving students to complete Honours in their final year of study. In place of two electives, eligible students can enrol into an ''''Honours Law'''' unit, which means completing your Honours won''''t require an additional year of study. </p> Professional accreditation <p>The UC Bachelor of Laws is recognised by the Legal Practitioners Admission Board of the Australian Capital Territory as providing the academic requirements for admission. Through mutual recognition, UC''''s Bachelor of Laws may serve as the basis for admission in all Australian jurisdictions. <br/> <br/>To be admitted to legal practice, in addition to completing UC''''s Bachelor of Laws, students must complete a practical legal training (PLT) course and satisfy character requirements. The PLT course is also referred to as the Graduate Diploma in Legal Practice, and is conveniently offered by external providers in the ACT.</p>',
    

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>Applicants who have completed a Diploma of Paralegal Services plus have a minimum of 12 months of documented full-time work experience as a paralegal or its equivalent will also be considered for admission. <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/30501">Diploma of Legal Services (BSB52215) (30501)</a> </p> <p><b>Canberra Institute Of Technology</b></p> <p> <a href="/credit/30489">Diploma of Paralegal Services (30489)</a> </p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><b>Universitas Indonesia</b></p> <p> <a href="/credit/32064">Bachelor of Laws - International Program (32064)</a> </p> <p><a href="#">See more</a></p>',
    apply_form = 'https://www.canberra.edu.au/course/SCB101/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '095937J';
UPDATE courses SET
    course_description = 'Improve community health outcomes <p>Do you want to make a lasting impact on the health and wellbeing of communities in Australia and around the world to help close the gap in the health status of socially excluded communities?</p> <p>UC’s Master of Public Health will help you gain the skills needed to analyse health information and plan and manage public health programs for populations, communities and individuals.</p> <p>This course is delivered in partnership with the esteemed <a href="https://www.canberra.edu.au/research/centres/hri">UC Health Research Institute</a> to help you gain the skills needed to analyse health information and plan and manage public health programs for communities and populations.</p> <p>Open to graduates from a wide range of fields, including clinical and non-clinical health professionals, you’ll delve into a broad range of topics including:</p> <ul> <li>Public, ecological and global health</li> <li>Epidemiology</li> <li>Biostatistics</li> <li>Health promotion,</li> <li>Health systems, policy and advocacy</li> <li>Communicable disease prevention and control</li> <li>Indigenous health</li> <li>Health economics</li> <li>Health and environmental sustainability</li> <li>health management including: <ul> <li>Program management </li> <li>Program evaluation.</li> </ul> </li> </ul> <p>Key features of the extended course are enhanced training in epidemiology and biostatistics and increased Work Integrated Learning opportunities, allowing you to apply your selected public health expertise in mentored workplace settings.</p> <p>This interdisciplinary degree has a focus on the ecological model of public health that emphasises and analyses the important interactions between the social, biological, economic and environmental influences on human health. </p> <p>You’ll graduate equipped with the skills and knowledge to confidently understand and deliver the core elements of public health. Your understanding of the multiple systems in which public health operates will allow you to investigate and apply interdisciplinary and creative approaches to address real-world problems within the goals of sustainable development. </p> <p>The course also has an emphasis on health equity and the development of culturally safe public health practices with a spotlight on First Nations’ health imperatives, locally and globally. <br/> </p> Study a Master of Public Health at UC and you will: <ul> <li>Be prepared to undertake core elements and competencies for public health.</li> <li>Understand the social determinants of health.</li> <li>Be equipped with the skills to develop health promoting and sustaining environments.</li> <li>Understand ecological public health and its real-world application.</li> <li>Be able to critically analyse public health problems and develop solutions.</li> <li>Possess an advanced understanding of the complex body of knowledge associated with contemporary and emerging local and global public health issues.</li> <li>Demonstrate the application of knowledge and skills in interdisciplinary approaches to public health with key stakeholders.</li> <li>Confidently plan and execute a substantial research-based project or capstone experience aligned with one of the key themes of the Sustainable Development Goals.<br/> </li> </ul> Work Integrated Learning (WIL) <p>Build valuable connections with your fellow students, resident researchers at the <a href="https://www.canberra.edu.au/research/centres/hri">Health Research Institute</a> and key stakeholders in Canberra such as local government, public agencies, industry, NGOs and community organisations. You’ll work through a substantial research-based project and a capstone placement experience where these networks will be key to nurturing an interdisciplinary approach to public health and gaining valuable ‘real-world’ experience to support your career progression.<br/> </p> Career opportunities <p>Completion of this course opens doors to a variety of careers in public health, including but not limited to:</p> <ul> <li>Public Health Officer</li> <li>Community Health Officer</li> <li>Health Policy Officer</li> <li>Health Project Officer</li> <li>Health Program Officer</li> <li>Health Educator</li> <li>Epidemiological Officer</li> <li>Healthy Lifestyle Project Officer</li> <li>Public Health Communications Officer</li> <li>Policy Officer</li> <li>Advocacy Officer.</li> </ul> Course highlights <p><b>- </b>Learn from our experienced and internationally recognised public health researchers at the well-renowned University of Canberra’s Health Research Institute. </p> <p>- Small class sizes, mentoring from faculty and the ability to choose electives that suit your career goals.</p> <p>- Gain real-world research experience by undertaking an applied research project that is suited to your individual career pathways and interests.</p> <p>- Gain unrivalled access to government agencies, peak bodies and community organisations in NSW, the ACT, and beyond.</p> <p>- Health equity is core to public health, and the University of Canberra is a world-leading university in Diversity and Inclusion.</p>',
    course_duration_per_week = 104,

    entry_requirements = '<p>A completed bachelor degree. Admission to this course is competitive. Applications will be assessed on the basis of academic merit and the number of available places.</p> Assumed knowledge <p>Students are expected to have basic competency in understanding of bio-statistical concepts.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/HLM102/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '115326M';
UPDATE courses SET
    course_description = 'Hit the ground running <p>Enhance your knowledge and gain a competitive advantage in a rapidly evolving industry.</p> <p>Acquire the key practical and theoretical competencies at the heart of today’s Communication and Media industries. Studying the Graduate Certificate in Communication will suit those looking to enhance their existing skills and knowledge and support them to become emerging leaders in the communications industry. </p> Study the Graduate Certificate in Communications at UC and you will: <ul> <li> <p> Master digital data analysis and visualisation </p> </li> <li> <p> Contextualise the role of innovation in the media environment </p> </li> <li> <p> Understand campaigns seeking to effect behaviour change </p> </li> </ul> Work Integrated Learning (WIL) <p>Enjoy an immersive online learning experience where you’ll be connected with an inspiring cohort of teachers and industry experts who will share their own experiences and mentor you through your learning.</p> Career opportunities <ul> <li>Public Relations Specialist </li> <li>Journalist </li> <li>Social Media Manager </li> <li>Communications Consultant </li> <li>Media Adviser </li> <li>Corporate Change Consultant </li> <li>Political Campaign Manager </li> </ul> Course specific information <p>To be eligible for the Graduate Certificate of Communications, applicants must have a recognised bachelor’s degree or equivalent from a recognised tertiary institution.<br/> Alternate entry pathways are available to IAP2 graduates without Bachelor''''s qualifications in accordance with the admission (for Undergraduate and Postgraduate Coursework Courses) procedure.<br/> Not sure if you meet the eligibility requirements for this course? Please get in touch.</p> Professional accreditation <p>None. </p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Applicants must have an undergraduate degree (AQF level 7) or equivalent. <br/> <br/>Students who have completed a Certificate in Engagement with International Association for Public Participation (IAP2) may be eligible to receive Credit for 1 unit (3 Credit Points) with relevant work experience into the Engagement Stream. <br/> <br/>Alternate entry pathways are available to IAP2 graduates without Bachelor''''s qualifications in accordance with the Admission (for Undergraduate and Postgraduate Coursework Courses) Procedure. <br/> <br/>Please refer to the Faculty of Arts and Design website for full details and instructions. <a href="https://www.canberra.edu.au/about-uc/faculties/arts-design/courses/iap2-graduates">https://www.canberra.edu.au/about-uc/faculties/arts-design/courses/iap2-graduates</a> <br/> <br/>In making an offer to an applicant, the University will give consideration to a range of factors including English proficiency, academic record and/or employment experience. <br/> <br/>You can use professional experience and prior learning to enter into a postgraduate qualification at UC through our Professional Pathway Entry program. If you have significant work experience or hold industry-recognised qualifications, this program could be your route to bypass undergraduate study and accelerate your career. Explore Professional Pathway Entry <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry">https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/professional-pathway-entry</a> <br/></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> <a href="#"></a> </td> <td> <a href="#"></a> </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/ARC201/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '040739C';
UPDATE courses SET
    course_description = 'The Graduate Diploma of Building &amp; Construction Information Management (GD-BCIM) aims to develop the extensive body of knowledge and professional practice in modelling, exchanging, maintaining, implementing and managing building and construction information. The course is designed to assist architects, building practitioners, construction engineers and project managers with consolidating the fundamental theories of BIM, technology-oriented BIM training, strengthening the modelling, management and simulation and enhancing the critical thinking and future competencies required for digital built environment. It will build on the existing knowledge and skills to deliver a comprehensive, flexible, robust and practice-led advanced BIM pedagogy. Professional accreditation <p>None.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Completed bachelor''''s degree or equivalent. The University of Canberra is a strong supporter of lifelong education and recognises that not everyone comes into university through traditional pathways. For example, we know that often people with significant industry experience are excellent students who gain a lot from completing our courses. <br/> <br/>If you do not hold a Bachelor degree, we may consider your previous related work experience through Recognition of Prior Learning (RPL). RPL enables admissions based on learning derived from work experience or a combination of qualification and work experience. The amount of work experience required will depend on your previous qualifications, ranging from 4 years (for example, if you have a TAFE advanced diploma) to 10 years if your highest qualification is a Year 12 certificate. In general, the following documentation is required as part of the RPL assessment. <br/> <br/>Please contact FAD.Student@canberra.edu.au if you''''d like to speak to someone about your eligibility. <br/>- an employer''''s letter validating work experience <br/>- examples of work, training certificates and course outlines <br/>- documented professional qualifications. <br/></p> Additional admission requirements <p>The applicants for the flexible and fully online modes of the program are required to have a functional computer to apply BIM software packages and tools.</p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/ABG101/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '108082G';
UPDATE courses SET
    course_description = 'Your creative career starts here <p>UC''''s Bachelor of Arts takes a practical approach to creativity. With project-based learning and opportunities to tackle real challenges, you’ll graduate prepared for a wide range of careers in the creative industries. Plus, with personal support from our academics and the broader university, you''''ll develop the skills and confidence to pursue the career path that''''s built for you.</p> An Arts degree shaped by you <p>We know not all Arts students are the same. That’s why our degrees are built to be flexible, so you can mix and match your learning to suit your interests. Alongside your Specialist Major, you can explore areas such as management, problem-solving, communication and more to create a study path that reflects who you are. Choose from one of the following Specialist Majors to make your degree your own:</p> <ul> <li>Creative Writing</li> <li>Culture &amp; Heritage</li> <li>Digital Media</li> <li>Film Production</li> <li>Game Development</li> <li>Global Studies</li> <li>Journalism</li> <li>Literary Studies</li> <li>Marketing Communication</li> <li>Sports Media</li> </ul> Work Integrated Learning <p>Work Integrated Learning (WIL) sits at the heart of the Bachelor of Arts. You’ll learn from industry-active professionals and leading academics while gaining practical experience through projects, internships, mentorships and professional placements.</p> <p>Your degree also includes units designed to build essential professional skills for the cultural and creative industries. Plus, you’ll have the chance to broaden your perspective with international work and study opportunities.</p> Career opportunities <p>Your Bachelor of Arts can open the door to many different paths. The opportunities you’ll have depend on your chosen Specialist Major, with potential careers including:</p> <ul> <li>Creative Copywriter</li> <li>Content Developer</li> <li>Museum Conservator</li> <li>Cultural Advisor</li> <li>Community Liaison Officer</li> <li>International Consultant</li> <li>Policy Advisor</li> <li>Project Manager</li> <li>Curator</li> <li>Heritage Consultant</li> <li>Campaign Manager</li> <li>Producer</li> <li>Publisher</li> <li>Film Producer</li> <li>Digital Producer</li> <li>Cinematographer<br/> </li> </ul> Course-specific information <p>Standard entry to this course is by selection rank, but you can also apply through Portfolio Entry. This option lets you showcase your creative potential and experience rather than relying on your academic results. Portfolio Entry is a great pathway if you’ve built experience outside of school or want to highlight your creative strengths. Learn more about <a href="https://www.canberra.edu.au/future-students/get-into-uc/admissions-programs/portfolio-entry">Portfolio Entry here.</a></p>',
    course_duration_per_week = 156,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>A credit transfer arrangement is available for this course for the following institutions:</p> <p><b>Credit Based On Work Experience</b></p> <p> <a href="/credit/35169">Equivalent Graduate Status / Work Experience / Veteran Tertiary Support Program (24CP) (35169)</a> </p> <p><b>Other Australian Tafe</b></p> <p> <a href="/credit/35190">Any Australian Certificate IV (AQF4) (12CP) (35190)</a> </p> <p> <a href="/credit/35168">Any Australian Diploma (AQF5) or Advanced Diploma (AQF6) (24CP) (35168)</a> </p> <p><b>University Of Canberra College</b></p> <p> <a href="/credit/35629">951AA Diploma of Communication (35629)</a> </p> <p> <a href="/credit/35608">199JA Diploma of Design (35608)</a> </p>',
    apply_form = 'https://www.canberra.edu.au/course/ARB009/2/2027',
    updated_at = NOW()
WHERE cricos_course_code = '116129H';
UPDATE courses SET
    course_description = 'Becoming a medication specialist starts here <p>If you''''re interested in a career as a medication specialist, then UC''''s Bachelor of Pharmacy is the degree for you. The course will equip you with the skills, knowledge, experience and qualifications required to become an official Australian registered pharmacist. This four-year, full-time course teaches the science behind the practical preparation of drugs and medicines to treat injuries, illnesses and deficiencies. It explores how to apply evidence-based knowledge, research and scientific theory to the clinical reasoning, treatment and evaluation of patients. This course also offers an embedded Honours program for high-achieving students looking to progress into pharmacy research or academic careers. If you''''re looking for a well-paid, fulfilling career helping others, register for the UC Bachelor of Pharmacy course now.<br/> </p> Study a Bachelor of Pharmacy at UC and you will: <ul> <br/> <li>Be educated in the theoretical, technical, written, practical and clinical components of pharmacy.</li> <li>Explore the science behind the preparation of drugs and medicines.</li> <li>Learn how to prepare a wide range of drugs and medicines.</li> <li>Understand how the human body reacts to certain medications, acquire and apply clinical reasoning, treatment and evaluation skills to life sciences.</li> <li>Combine theory with hands-on experience in practical laboratory classes and clinical placements.</li> <li>Gain the necessary knowledge, exposure, attitudes and clinical decision-making skills required to practice as a pharmacist and achieve a globally recognised accreditation.<br/> </li> </ul> Work Integrated Learning (WIL) <p>WIL allows students to work alongside, with, or for professional or government organisations, so you''''ll gain valuable hands-on experience and build professional relationships before you graduate. This approach ensures that UC students are aware of what is going on in their specialist industries, possess a wide range of professional contacts, and have a higher chance of employment upon graduation. </p> <p>As part of this course, each student will have the opportunity to participate in multiple 2-week placements that take place over the winter semesters at metropolitan, rural or regional community and hospital pharmacies.</p> <p>Students will also get to participate in half-day or full-day work placements throughout each of the teaching semesters. <br/> </p> Career opportunities <p>A registered UC Bachelor of Pharmacy graduate is an important component of any healthcare team, as they can assess a variety of medical ailments and possess the knowledge to recommend a range of drugs and medicines to help resolve or manage multiple medical issues.</p> <p>Also, as the global aging population continues to grow, the demand for qualified pharmacy graduates capable of offering additional services such asthma care and blood pressure monitoring is expected to increase.</p> <p>In addition, each UC Bachelor of Pharmacy graduate leaves with a comprehensive list of industry and stakeholder contacts and can move into positions such as: </p> <ul> <br/> <li>Practicing pharmacist, working in a community or a hospital pharmacy.</li> <li>Regulator within the government and broader pharmaceutical industry.<br/> </li> </ul> Course-specific information <p>As part of the degree, students will be required to undertake clinical placements and must be able to prove that they are fully vaccinated and able to pass standard police checks to comply with government health and security regulations.</p> Professional accreditation <p>This course is fully accredited by the Australian Pharmacy Council.</p>',
    course_duration_per_week = 208,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Additional admission requirements <p>All students in the Bachelor of Pharmacy course are required to complete clinical practice placement in blocks of time, often outside of teaching time. These clinical practice placements are essential to the program. Prior to commencing clinical practice, all students need to present a complete immunisation schedule as a requirement of the ACT and NSW health departments. All students are required to undergo an Australian Federal Police Record check prior to undertaking clinical placement in the ACT, and a NSW Police check before undertaking placement in NSW. <br/> <br/>All pharmacy students will be registered as students with the Pharmacy Board of Australia after admission to the Bachelor of Pharmacy course</p> Assumed knowledge <p>ACT: Mathematical Methods major and either Biology or Human Movement major(s); and Chemistry or Physics major(s). NSW: Mathematics and either Biology or Human Movement, and Physics or Chemistry.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/HLB301/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '106125F';
UPDATE courses SET
    course_description = 'A connected law and business degree, built for today’s workplaces <p>UC’s Bachelor of Laws/Bachelor of Business brings law and business together in a way that reflects how they’re used in practice. You’ll focus on corporate and commercial law, build your ability to solve real legal problems, and shape your degree with electives in areas such as IT, accounting, human resources and marketing.</p> <p>If you’re aiming to move into management, you’ll develop a strong understanding of core business areas, along with the practical skills you’ll need to adapt in changing workplaces. You’ll be supported by experienced teachers who’ll help you build your legal knowledge and advocacy skills, while showing you how law connects to its theory, history and real-world application.</p> <p>You’ll learn in small classes, with access to modern facilities and strong industry connections. Through our links to employers across Canberra’s public sector, law firms and NGOs, the National Centre for Corporate Law and the National Institute of Governance, you’ll start building your professional network early. You’ll also have opportunities to apply what you’ve learned. Complete a law internship, study overseas, or fast-track your progress through our winter term. </p> Combine a Bachelor of Business and Bachelor of Laws at UC and you will: <ul> <li>Build a strong foundation in law, preparing you for legal practice or related careers.</li> <li>Communicate clearly and work across professional and cultural contexts.</li> <li>Focus your law studies on areas of interest, with an emphasis on commercial law.</li> <li>Develop skills across key business areas, including human resources, finance, accounting, marketing and business analytics.</li> <li>Learn to analyse problems, think critically and evaluate information in a structured and practical way.</li> </ul> Career opportunities <p>With a Bachelor of Laws/Bachelor of Business, you’ll graduate with the qualifications and skills to move across both legal and business settings. You could go on to work as a:</p> <ul> <li>Barrister</li> <li>Solicitor</li> <li>Policy adviser</li> <li>Legislative drafter</li> <li>Advocate</li> <li>Researcher</li> <li>Manager</li> <li>Consultant</li> <li>Entrepreneur</li> </ul> <p>This degree gives you a clear path into legal and business careers, with the flexibility to move between them as your goals evolve.</p> Professional accreditation <p>Refer to individual courses</p>',
    course_duration_per_week = 260,

    entry_requirements = '<p>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: <br/>- Year 12 ATAR <br/>- other Australian Qualification <br/>- work experience <br/>- overseas qualification <br/> <br/>We also offer a number of entry initiatives that give you the opportunity to gain entry to the University via alternate pathway programs and admissions schemes. <br/>More information is available on our Alternative Entry page: <a href="http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry">http://www.canberra.edu.au/future-students/applications/apply-now/alternative-entry</a></p> Assumed knowledge <p>None.</p> Periods course is open for new admissions <table> <tbody> <tr> <th>Year</th> <th>Location</th> <th>Teaching period</th> <th>Teaching start date</th> <th>Domestic</th> <th>International</th> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 1 </td> <td>15 February 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> <tr> <td>2027</td> <td>Bruce, Canberra</td> <td>Semester 2 </td> <td>09 August 2027</td> <td> Open for domestic admissions </td> <td> Open for international admissions </td> </tr> </tbody> </table> Credit arrangements <p>There are currently no formal credit transfer arrangements for entry to this course. Any previous study or work experience will only be considered as part of the application process in accordance with current <a href="https://policies.canberra.edu.au/document/view-current.php?id=222">course rules and university policy</a>.</p>',
    apply_form = 'https://www.canberra.edu.au/course/MGSC03/1/2027',
    updated_at = NOW()
WHERE cricos_course_code = '099011A';
